import smbus
import time
import signal
import sys

# ADS1115 constants
ADS1115_I2C_ADDR = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Config register bit fields
ADS1115_OS_START = 0x8000
ADS1115_MUX_BASE = 0x4000  # single-ended AIN0 vs GND
ADS1115_PGA_4_096V = 0x0200
ADS1115_MODE_SINGLE = 0x0100
ADS1115_DR_128SPS = 0x0080
ADS1115_CQUE_NONE = 0x0003

# Conversion timeout (seconds)
CONV_TIMEOUT = 0.1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _swap_bytes(word):
    return ((word & 0xFF) << 8) | ((word >> 8) & 0xFF)


def _read_config(bus, channel):
    """Read the 16-bit config register for the given single-ended channel (0-3)."""
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid channel {channel}; must be 0-3")
    config = (
        ADS1115_OS_START
        | (ADS1115_MUX_BASE + (channel << 12))
        | ADS1115_PGA_4_096V
        | ADS1115_MODE_SINGLE
        | ADS1115_DR_128SPS
        | ADS1115_CQUE_NONE
    )
    bus.write_i2c_block_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, [(config >> 8) & 0xFF, config & 0xFF])


def _read_conversion(bus):
    """Read the 16-bit raw conversion result (big-endian)."""
    data = bus.read_i2c_block_data(ADS1115_I2C_ADDR, ADS1115_REG_CONVERSION, 2)
    return _swap_bytes((data[0] << 8) | data[1])


def _wait_for_conversion(bus):
    """Poll the OS bit until it reads 1 (conversion complete) or timeout."""
    deadline = time.monotonic() + CONV_TIMEOUT
    while time.monotonic() < deadline:
        config = _swap_bytes((bus.read_i2c_block_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, 2)[0] << 8) | bus.read_i2c_block_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, 2)[1])
        if config & ADS1115_OS_START:
            return True
        time.sleep(0.001)
    return False


def read_adc_channel(bus, channel):
    """Trigger a single-shot conversion on *channel* and return the raw signed value."""
    _read_config(bus, channel)
    if not _wait_for_conversion(bus):
        raise TimeoutError(f"ADS1115 conversion timeout on channel {channel}")
    return _read_conversion(bus)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: Failed to open I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            values = []
            for ch in range(4):
                try:
                    raw = read_adc_channel(bus, ch)
                    # Convert to signed 16-bit
                    if raw >= 0x8000:
                        raw -= 0x10000
                    values.append(raw)
                except (TimeoutError, OSError) as e:
                    values.append(f"ERR: {e}")

            print(f"Channel 0: {values[0]:05d}  Channel 1: {values[1]:05d}  Channel 2: {values[2]:05d}  Channel 3: {values[3]:05d}")
            time.sleep(0.05)

    except KeyboardInterrupt:
        pass
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("\nExiting program.")


if __name__ == "__main__":
    main()

