import time
import signal
import sys
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
import RPi.GPIO as GPIO

# --- Pin definitions (BCM) ---
DIR_PIN = 20
STEP_PIN = 21
MS0_PIN = 14
MS1_PIN = 15
PWM_FREQ = 500
ADC_CHANNEL = 0
ADC_GAIN = 1

# --- Global state for cleanup ---
_running = True
_pwm = None

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    global _pwm
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    GPIO.cleanup()

def _init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DIR_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(STEP_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(MS0_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(MS1_PIN, GPIO.OUT, initial=GPIO.LOW)

def _init_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def _init_sensors(i2c):
    try:
        accel = adafruit_lsm303_accel.LSM303_Accel(i2c)
        mag = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        return accel, mag
    except Exception as e:
        print(f"Error initializing LSM303 sensors: {e}", file=sys.stderr)
        return None, None

def _init_adc(i2c):
    try:
        ads = ADS.ADS1015(i2c, address=0x48)
        ads.gain = ADC_GAIN
        chan = AnalogIn(ads, ADC_CHANNEL)
        return ads, chan
    except Exception as e:
        print(f"Error initializing ADS1015: {e}", file=sys.stderr)
        return None, None

def _read_adc(chan):
    try:
        return chan.value
    except Exception as e:
        print(f"Error reading ADC: {e}", file=sys.stderr)
        return None

def _read_accel(accel):
    try:
        return accel.acceleration
    except Exception as e:
        print(f"Error reading accelerometer: {e}", file=sys.stderr)
        return None

def _read_mag(mag):
    try:
        return mag.magnetic
    except Exception as e:
        print(f"Error reading magnetometer: {e}", file=sys.stderr)
        return None

def _calculate_heading(mag):
    if mag is None:
        return None
    x, y, _ = mag
    angle = (180.0 + math.atan2(y, x)) % 360.0
    return angle

def _set_pwm_duty(pwm, duty):
    if pwm is None:
        return
    try:
        pwm.ChangeDutyCycle(duty)
    except Exception as e:
        print(f"Error setting PWM duty cycle: {e}", file=sys.stderr)

def main():
    global _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_gpio()

    i2c = _init_i2c()
    if i2c is None:
        _cleanup()
        sys.exit(1)

    accel, mag = _init_sensors(i2c)
    ads, chan = _init_adc(i2c)

    if chan is None:
        _cleanup()
        sys.exit(1)

    try:
        _pwm = GPIO.PWM(STEP_PIN, PWM_FREQ)
        _pwm.start(0)
    except Exception as e:
        print(f"Error starting PWM: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("Starting main loop. Press Ctrl+C to exit.")

    try:
        while _running:
            adc_value = _read_adc(chan)
            if adc_value is not None:
                voltage = adc_value * 4.096 / 32767.0
                duty = int(max(0, min(255, adc_value / 32767.0 * 255)))
                _set_pwm_duty(_pwm, duty)
                print(f"ADC: {adc_value}, Voltage: {voltage:.3f}, PWM Duty: {duty}")
            else:
                _set_pwm_duty(_pwm, 0)
                print("ADC read failed; PWM set to 0.")

            accel_data = _read_accel(accel)
            if accel_data is not None:
                print(f"Acceleration (m/s^2): ({accel_data[0]:.3f}, {accel_data[1]:.3f}, {accel_data[2]:.3f})")
            else:
                print("Acceleration read failed.")

            mag_data = _read_mag(mag)
            if mag_data is not None:
                heading = _calculate_heading(mag_data)
                if heading is not None:
                    print(f"Magnetic Heading: {heading:.2f} degrees")
                else:
                    print("Magnetic heading calculation failed.")
            else:
                print("Magnetometer read failed.")

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        _cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    import math
    main()

