import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def format_value(value):
    """Defensively format a sensor value to avoid crashes in emulated environments."""
    if value is None:
        return "N/A"
    try:
        return str(value)
    except Exception:
        return "N/A"

def log_heart_rate(timestamp, heart_rate):
    """Append a timestamped heart rate reading to the log file."""
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp}, {heart_rate}\n")
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        sensor.setup()
        print("MAX30102 initialized successfully.")
    except Exception as e:
        print(f"Failed to initialize MAX30102 sensor: {e}", file=sys.stderr)
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        sys.exit(1)

    previous_samples = []
    last_sample_time = time.monotonic()

    try:
        while _running:
            loop_start = time.monotonic()

            try:
                ir_sample = sensor.ir
                red_sample = sensor.red
            except Exception as e:
                print(f"Error reading sensor data: {e}", file=sys.stderr)
                ir_sample = None
                red_sample = None

            current_time = time.monotonic()
            elapsed = current_time - last_sample_time
            last_sample_time = current_time

            if ir_sample is not None and red_sample is not None:
                previous_samples.append((ir_sample, red_sample))
                while previous_samples and (current_time - previous_samples[0][0]) > WINDOW_SECONDS:
                    previous_samples.pop(0)

                if len(previous_samples) >= 2:
                    ir_values = [s[0] for s in previous_samples]
                    red_values = [s[1] for s in previous_samples]
                    ir_peaks = 0
                    red_peaks = 0
                    for i in range(1, len(ir_values)):
                        if ir_values[i] > ir_values[i - 1]:
                            ir_peaks += 1
                        if red_values[i] > red_values[i - 1]:
                            red_peaks += 1

                    if elapsed > 0:
                        ir_bpm = (ir_peaks / elapsed) * 60.0
                        red_bpm = (red_peaks / elapsed) * 60.0
                        heart_rate = (ir_bpm + red_bpm) / 2.0
                    else:
                        heart_rate = 0.0

                    timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
                    log_heart_rate(timestamp, heart_rate)
                    print(f"Heart Rate: {heart_rate:.2f} BPM")

            sleep_time = SAMPLE_INTERVAL - (time.monotonic() - loop_start)
            if sleep_time > 0:
                time.sleep(sleep_time)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

