import io
import time
import json
import signal
import logging
import threading
import queue
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    LED = None
    GPIOZeroError = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_CONFIG = {
    "camera_resolution": (640, 480),
    "camera_framerate": 10,
    "motion_detection_threshold": 25,
    "max_queue_size": 10,
    "gpio_pin": 17,
    "led_activation_duration": 2,
    "camera_warmup_time": 2
}

running = True

def signal_handler(sig, frame):
    global running
    logging.info("SIGINT received, shutting down...")
    running = False

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        logging.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def initialize_camera(config):
    try:
        picam2 = Picamera2()
        camera_resolution = tuple(config["camera_resolution"])
        camera_framerate = config["camera_framerate"]
        picam2.configure(picam2.create_video_configuration(main={"size": camera_resolution, "format": "RGB888"}))
        picam2.start()
        time.sleep(config["camera_warmup_time"])
        logging.info(f"Camera initialized with resolution {camera_resolution} and framerate {camera_framerate}")
        return picam2
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def initialize_led(gpio_pin):
    if LED is None:
        logging.warning("gpiozero not available. LED functionality disabled.")
        return None
    try:
        led = LED(gpio_pin)
        led.off()
        logging.info(f"LED initialized on GPIO pin {gpio_pin}")
        return led
    except GPIOZeroError as e:
        logging.error(f"Error initializing LED on GPIO pin {gpio_pin}: {e}")
        return None

def capture_frame(picam2):
    try:
        frame = picam2.capture_array()
        return frame
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def encode_frame(frame):
    try:
        from PIL import Image
        img = Image.fromarray(frame)
        buf = io.BytesIO()
        img.save(buf, format='JPEG')
        buf.seek(0)
        return buf.read()
    except Exception as e:
        logging.error(f"Error encoding frame: {e}")
        return None

def detect_motion(frame1, frame2, threshold):
    try:
        diff = np.abs(frame1.astype(np.int16) - frame2.astype(np.int16))
        mean_diff = np.mean(diff)
        return mean_diff > threshold
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False

def trigger_alert(led, duration):
    if led is None:
        logging.warning("LED not initialized. Skipping alert.")
        return
    try:
        led.on()
        logging.warning("Motion detected! Activating alert.")
        time.sleep(duration)
        led.off()
        logging.info("Alert deactivated.")
    except GPIOZeroError as e:
        logging.error(f"Error triggering alert: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    config = load_config("config.json")
    picam2 = initialize_camera(config)
    led = initialize_led(config["gpio_pin"])

    if picam2 is None:
        logging.error("Camera initialization failed. Exiting.")
        if led is not None:
            led.close()
        return

    frame_queue = queue.Queue(maxsize=config["max_queue_size"])
    previous_frame = None

    try:
        while running:
            frame = capture_frame(picam2)
            if frame is None:
                time.sleep(0.1)
                continue

            if frame_queue.full():
                try:
                    frame_queue.get_nowait()
                except queue.Empty:
                    pass

            frame_queue.put(frame)

            if previous_frame is not None:
                if detect_motion(previous_frame, frame, config["motion_detection_threshold"]):
                    alert_timer = threading.Timer(config["led_activation_duration"], trigger_alert, args=(led, config["led_activation_duration"]))
                    alert_timer.daemon = True
                    alert_timer.start()

            previous_frame = frame
            time.sleep(0.1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources...")
        if led is not None:
            led.close()
        if picam2 is not None:
            picam2.stop()
            picam2.close()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

