import time
import datetime
import sqlite3
import signal
import sys
import os

try:
    import smbus2 as smbus
except ImportError:
    smbus = None

try:
    from adafruit_bmp280 import BMP280
    from adafruit_bme280 import BME280
    from adafruit_ms8607 import MS8607
except ImportError:
    BMP280 = None
    BME280 = None
    MS8607 = None

CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"

running = True
db_conn = None

def log_error(message):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)

def signal_handler(sig, frame):
    global running
    running = False

def load_config():
    config = {}
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    log_error(f"Invalid config line: {line}")
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                config[key] = value
    except FileNotFoundError:
        log_error(f"Configuration file not found: {CONFIG_FILE}")
    except Exception as e:
        log_error(f"Error loading configuration: {e}")
    return config

def init_database():
    global db_conn
    try:
        db_conn = sqlite3.connect(DATABASE_FILE)
        cursor = db_conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database initialization error: {e}")
        db_conn = None

def store_data(sensor_type, sensor_id, pressure, temperature, humidity):
    if db_conn is None:
        return
    try:
        timestamp = datetime.datetime.now().isoformat()
        cursor = db_conn.cursor()
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database store error: {e}")

def validate_data(sensor_type, pressure, temperature, humidity):
    if pressure is None or temperature is None:
        return False
    if not (70000 <= pressure <= 110000):
        log_error(f"Invalid pressure {pressure} Pa for {sensor_type}")
        return False
    if not (-20 <= temperature <= 50):
        log_error(f"Invalid temperature {temperature} C for {sensor_type}")
        return False
    if sensor_type in ("BME280", "MS8607"):
        if humidity is None:
            return False
        if not (0 <= humidity <= 100):
            log_error(f"Invalid humidity {humidity} % for {sensor_type}")
            return False
    return True

def read_bmp280(bus, address, sensor_id):
    try:
        sensor = BMP280(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        return pressure, temperature, None
    except Exception as e:
        log_error(f"BMP280 read error at 0x{address:02X}: {e}")
        return None, None, None

def read_bme280(bus, address, sensor_id):
    try:
        sensor = BME280(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        humidity = sensor.humidity
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"BME280 read error at 0x{address:02X}: {e}")
        return None, None, None

def read_ms8607(bus, address, sensor_id):
    try:
        sensor = MS8607(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"MS8607 read error at 0x{address:02X}: {e}")
        return None, None, None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    init_database()

    if not config:
        log_error("No sensors configured. Exiting.")
        if db_conn:
            db_conn.close()
        sys.exit(0)

    sampling_interval = 60
    if "Sampling_Interval_Seconds" in config:
        try:
            sampling_interval = int(config["Sampling_Interval_Seconds"])
        except ValueError:
            log_error("Invalid Sampling_Interval_Seconds. Using default 60 seconds.")

    if smbus is None:
        log_error("smbus2 not installed. Exiting.")
        if db_conn:
            db_conn.close()
        sys.exit(0)

    try:
        bus = smbus.SMBus(1)
    except Exception as e:
        log_error(f"Failed to open I2C bus 1: {e}")
        if db_conn:
            db_conn.close()
        sys.exit(0)

    sensors = []
    for i in range(1, 4):
        sensor_type_key = f"Sensor{i}_Type"
        sensor_address_key = f"Sensor{i}_Address"
        sensor_id_key = f"Sensor{i}_ID"

        if sensor_type_key not in config:
            continue

        sensor_type = config[sensor_type_key]
        sensor_address = int(config[sensor_address_key], 16) if sensor_address_key in config else None
        sensor_id = config[sensor_id_key] if sensor_id_key in config else f"Sensor{i}"

        if sensor_type == "BMP280":
            if BMP280 is None:
                log_error("adafruit_bmp280 not installed. Skipping BMP280.")
                continue
            sensors.append({"type": "BMP280", "address": sensor_address, "id": sensor_id, "read_func": read_bmp280})
        elif sensor_type == "BME280":
            if BME280 is None:
                log_error("adafruit_bme280 not installed. Skipping BME280.")
                continue
            sensors.append({"type": "BME280", "address": sensor_address, "id": sensor_id, "read_func": read_bme280})
        elif sensor_type == "MS8607":
            if MS8607 is None:
                log_error("adafruit_ms8607 not installed. Skipping MS8607.")
                continue
