except ImportError:
    smbus = None

try:
    from adafruit_bmp280 import BMP280
    from adafruit_bme280 import BME280
    from adafruit_ms8607 import MS8607
except ImportError:
    BMP280 = None
    BME280 = None
    MS8607 = None

CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"

running = True
db_conn = None

def log_error(message):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)

def signal_handler(sig, frame):
    global running
    running = False

def load_config():
    config = {}
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    log_error(f"Invalid config line: {line}")
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                config[key] = value
    except FileNotFoundError:
        log_error(f"Configuration file not found: {CONFIG_FILE}")
    except Exception as e:
        log_error(f"Error loading configuration: {e}")
    return config

def init_database():
    global db_conn
    try:
        db_conn = sqlite3.connect(DATABASE_FILE)
        cursor = db_conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database initialization error: {e}")
        db_conn = None

def store_data(sensor_type, sensor_id, pressure, temperature, humidity):
    if db_conn is None:
        return
    try:
        timestamp = datetime.datetime.now().isoformat()
        cursor = db_conn.cursor()
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database store error: {e}")

def validate_data(sensor_type, pressure, temperature, humidity):
    if pressure is None or temperature is None:
        return False
    if not (70000 <= pressure <= 110000):
        log_error(f"Invalid pressure {pressure} Pa for {sensor_type}")
        return False
    if not (-20 <= temperature <= 50):
        log_error(f"Invalid temperature {temperature} C for {sensor_type}")
        return False
    if sensor_type in ("BME280", "MS8607"):
        if humidity is None:
            return False
        if not (0 <= humidity <= 100):
            log_error(f"Invalid humidity {humidity} % for {sensor_type}")
            return False
    return True

def read_bmp280(bus, address, sensor_id):
    try:
        sensor = BMP280(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        return pressure, temperature, None
    except Exception as e:
        log_error(f"BMP280 read error at 0x{address:02X}: {e}")
        return None, None, None

def read_bme280(bus, address, sensor_id):
    try:
        sensor = BME280(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        humidity = sensor.humidity
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"BME280 read error at 0x{address:02X}: {e}")
        return None, None, None

def read_ms8607(bus, address, sensor_id):
    try:
        sensor = MS8607(bus, address=address)
        pressure = sensor.pressure
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return pressure, temperature, humidity
    except Exception as e:
        log_error(f"MS8607 read error at 0x{address:02X}: {e}")
        return None, None, None

def main():
