        log_error("No sensors configured. Exiting.")
        if db_conn:
            db_conn.close()
        sys.exit(0)

    sampling_interval = 60
    if "Sampling_Interval_Seconds" in config:
        try:
            sampling_interval = int(config["Sampling_Interval_Seconds"])
        except ValueError:
            log_error("Invalid Sampling_Interval_Seconds. Using default 60 seconds.")

    if smbus is None:
        log_error("smbus2 not installed. Exiting.")
        if db_conn:
            db_conn.close()
        sys.exit(0)

