        sys.exit(0)

    sensors = []
    for i in range(1, 4):
        sensor_type_key = f"Sensor{i}_Type"
        sensor_address_key = f"Sensor{i}_Address"
        sensor_id_key = f"Sensor{i}_ID"

        if sensor_type_key not in config:
            continue

        sensor_type = config[sensor_type_key]
        sensor_address = int(config[sensor_address_key], 16) if sensor_address_key in config else None
        sensor_id = config[sensor_id_key] if sensor_id_key in config else f"Sensor{i}"

        if sensor_type == "BMP280":
            if BMP280 is None:
                log_error("adafruit_bmp280 not installed. Skipping BMP280.")
                continue
            sensors.append({"type": "BMP280", "address": sensor_address, "id": sensor_id, "read_func": read_bmp280})
        elif sensor_type == "BME280":
