# Raspberry Pi Zero W — UART ultrasonic distance logger
# Reads distance from /dev/serial0 (9600 8N1) and logs to file + console.

import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
LOG_FILE = "distance_log.txt"
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baudrate):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
        print(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as exc:
        print(f"Error opening serial port {port}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening serial port {port}: {exc}", file=sys.stderr)
        return None


def read_distance(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        print(f"Invalid data (not a float): {text!r}", file=sys.stderr)
        return None


def log_distance(log_file, timestamp, distance):
    try:
        with open(log_file, "a", encoding="utf-8") as fh:
            fh.write(f"{timestamp},{distance:.2f}\n")
            fh.flush()
    except OSError as exc:
        print(f"Error writing to log file {log_file}: {exc}", file=sys.stderr)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            distance = read_distance(ser)
            if distance is not None:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_distance(LOG_FILE, timestamp, distance)
                print(f"{timestamp},{distance:.2f}")
            time.sleep(READ_INTERVAL_S)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

