            logger.error(f"Failed to write default config: {e}")
            sys.exit(1)
    else:
        config.read(CONFIG_FILE)
    storage_dir = Path(config.get("DEFAULT", "StorageDirectory"))
    try:
        disk_space_threshold = int(config.get("DEFAULT", "DiskSpaceThresholdMB"))
    except ValueError:
        logger.error("Invalid DiskSpaceThresholdMB; using default 100.")
        disk_space_threshold = 100
    log_file = config.get("DEFAULT", "LogFile")
    try:
        pir_pin = int(config.get("DEFAULT", "PIRPin"))
    except ValueError:
        logger.error("Invalid PIRPin; using default 4.")
        pir_pin = 4
    return storage_dir, disk_space_threshold, log_file, pir_pin


def setup_logging(log_file):
    global logger
    log_dir = Path(log_file).parent
    try:
        log_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"Cannot create log directory {log_dir}: {e}", file=sys.stderr)
        sys.exit(1)
    logger = logging.getLogger("surveillance")
    logger.setLevel(logging.INFO)
    fmt = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    try:
        fh = logging.FileHandler(log_file)
        fh.setFormatter(fmt)
        logger.addHandler(fh)
    except OSError as e:
        print(f"Cannot open log file {log_file}: {e}", file=sys.stderr)
        sys.exit(1)
    sh = logging.StreamHandler()
    sh.setFormatter(fmt)
    logger.addHandler(sh)
    logger.info("Logging initialized.")


def initialize_camera():
    global camera
    if Picamera2 is None:
        logger.warning("picamera2 library not available; camera disabled.")
        return None
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        logger.info("Camera initialized successfully.")
        return camera
    except Exception as e:
        logger.error(f"Failed to initialize camera: {e}")
        camera = None
        return None


def initialize_gpio(pin):
    global pir_pin
    if GPIO is None:
        logger.warning("RPi.GPIO library not available; PIR disabled.")
        return None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logger.info(f"GPIO pin {pin} initialized as input with pull-down.")
        pir_pin = pin
        return pin
    except Exception as e:
        logger.error(f"Failed to initialize GPIO pin {pin}: {e}")
        pir_pin = None
        return None


def ensure_directory_exists(path):
    try:
        path.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        logger.error(f"Cannot create directory {path}: {e}")
        return False
    return True


def capture_images(storage_dir, quality, bitrate):
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    image_dir = storage_dir / timestamp
    if not ensure_directory_exists(image_dir):
        return
    for i in range(3):
        if not running:
            return
        filename = image_dir / f"image_{i+1}.jpg"
        try:
            camera.capture_file(str(filename), format="jpeg", quality=quality)
            logger.info(f"Captured image: {filename}")
        except Exception as e:
            logger.error(f"Failed to capture image {i+1}: {e}")
        if i < 2 and running:
            time.sleep(0.5)


def capture_video(storage_dir, bitrate, fps):
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    video_dir = storage_dir / timestamp
    if not ensure_directory_exists(video_dir):
        return
    filename = video_dir / f"video.h264"
    try:
        encoder = H264Encoder(bitrate=bitrate, framerate=fps)
        output = FileOutput(str(filename))
        camera.start_recording(encoder, output)
        logger.info(f"Started recording video: {filename}")
        time.sleep(5)
        camera.stop_recording()
        logger.info(f"Stopped recording video: {filename}")
    except Exception as e:
        logger.error(f"Failed to capture video: {e}")


def manage_disk_space(storage_dir, threshold_mb):
    try:
        statvfs = os.statvfs(str(storage_dir))
        free_mb = (statvfs.f_bavail * statvfs.f_frsize) / (1024 * 1024)
        if free_mb < threshold_mb:
            logger.warning(f"Disk space low: {free_mb:.1f} MB free, threshold {threshold_mb} MB.")
            files = []
            for root, _, filenames in os.walk(storage_dir):
                for fn in filenames:
                    path = Path(root) / fn
                    try:
                        mtime = os.path.getmtime(path)
                        files.append((path, mtime))
                    except OSError:
                        continue
            files.sort(key=lambda x: x[1])
            bytes_to_free = (threshold_mb - free_mb) * 1024 * 1024
            bytes_freed = 0
            for path, _ in files:
                try:
                    size = path.stat().st_size
                    if size > bytes_to_free:
                        break
                    os.remove(path)
                    bytes_freed += size
                    logger.info(f"Deleted file to free disk space: {path}")
                except OSError as e:
                    logger.error(f"Failed to delete file {path}: {e}")
            free_mb = (os.statvfs(str(storage_dir)).f_bavail * os.statvfs(str(storage_dir)).f_frsize) / (1024 * 1024)
            logger.info(f"Disk space after cleanup: {free_mb:.1f} MB free.")
    except OSError as e:
        logger.error(f"Failed to manage disk space: {e}")


def motion_detected(channel):
    global running
    if not running:
        return
    logger.info("Motion detected!")
    capture_images(storage_dir, int(DEFAULT_CONFIG["ImageQuality"]), int(DEFAULT_CONFIG["Bitrate"]))
    if running:
        capture_video(storage_dir, int(DEFAULT_CONFIG["VideoBitrate"]), int(DEFAULT_CONFIG["VideoFPS"]))
    manage_disk_space(storage_dir, disk_space_threshold)


def main():
    global running, camera, pir_pin
    storage_dir, disk_space_threshold, log_file, pir_pin = load_config()
    setup_logging(log_file)
    logger.info("Starting surveillance system...")
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    camera = initialize_camera()
    pir_pin = initialize_gpio(pir_pin)
    if pir_pin is not None and camera is not None:
        try:
            GPIO.add_event_detect(pir_pin, GPIO.RISING, callback=motion_detected, bouncetime=300)
            logger.info("Surveillance system running. Press Ctrl+C to exit.")
            while running:
                time.sleep(1)
        except Exception as e:
            logger.error(f"Unexpected error in main loop: {e}")
        finally:
            if camera is not None:
                try:
                    camera.stop()
                    camera.close()
                    logger.info("Camera closed.")
                except Exception as e:
                    logger.error(f"Error closing camera: {e}")
            if pir_pin is not None:
                try:
                    GPIO.remove_event_detect(pir_pin)
                    GPIO.cleanup()
                    logger.info("GPIO cleaned up.")
                except Exception as e:
                    logger.error(f"Error cleaning up GPIO: {e}")
    else:
        logger.warning("Camera or GPIO initialization failed; running in degraded mode.")
        try:
            while running:
                time.sleep(1)
        except KeyboardInterrupt:
            pass
    logger.info("Surveillance system stopped.")


if __name__ == "__main__":
    main()

