import cv2
import numpy as np
import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

# Constants
CAMERA_WIDTH = 640
CAMERA_HEIGHT = 480
CAMERA_FRAMERATE = 16
SERVO_PIN_AZIMUTH = 7
SERVO_PIN_ELEVATION = 13
SERVO_FREQUENCY = 50
SERVO_INITIAL_DUTY_CYCLE = 7.0
SERVO_MAX_DUTY_CYCLE = 12.0
SERVO_INCREMENT = 0.1
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 115200
MIN_OBJECT_AREA = 16

# Global state for cleanup
running = True
api = None
camera = None
servo_azimuth = None
servo_elevation = None

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global api, camera, servo_azimuth, servo_elevation
    print("Cleaning up resources...")
    if servo_azimuth is not None:
        servo_azimuth.close()
    if servo_elevation is not None:
        servo_elevation.close()
    if api is not None:
        try:
            api.stop()
        except Exception:
            pass
    if camera is not None:
        camera.release()
    cv2.destroyAllWindows()
    print("Cleanup complete.")

def initialize_camera():
    global camera
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_WIDTH)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, CAMERA_HEIGHT)
        camera.set(cv2.CAP_PROP_FPS, CAMERA_FRAMERATE)
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def initialize_servos():
    global servo_azimuth, servo_elevation
    try:
        servo_azimuth = PWMOutputDevice(SERVO_PIN_AZIMUTH, frequency=SERVO_FREQUENCY, initial_value=SERVO_INITIAL_DUTY_CYCLE / 100.0)
        servo_elevation = PWMOutputDevice(SERVO_PIN_ELEVATION, frequency=SERVO_FREQUENCY, initial_value=SERVO_INITIAL_DUTY_CYCLE / 100.0)
        return servo_azimuth, servo_elevation
    except GPIOZeroError as e:
        print(f"Error initializing servos: {e}")
        return None, None

def initialize_api():
    global api
    try:
        api = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(2)
        return api
    except serial.SerialException as e:
        print(f"Error initializing serial communication: {e}")
        return None

def segment_red_object(frame):
    hsv_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask1 = cv2.inRange(hsv_roi, np.array([160, 160, 0]), np.array([190, 255, 255]))
    ycr_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask2 = cv2.inRange(ycr_roi, np.array((0., 165., 0.)), np.array((255., 255., 255.)))
    mask = mask1 | mask2
    mask = cv2.erode(mask, None, iterations=2)
    mask = cv2.dilate(mask, None, iterations=2)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if contours:
        largest_contour = max(contours, key=cv2.contourArea)
        if cv2.contourArea(largest_contour) > MIN_OBJECT_AREA:
            x, y, w, h = cv2.boundingRect(largest_contour)
            return (x, y, w, h)
    return None

def send_command(api, command):
    if api is None:
        return
    try:
        api.write(command.encode('utf-8'))
    except serial.SerialException as e:
        print(f"Error sending command: {e}")

def main():
    global running, api, camera, servo_azimuth, servo_elevation

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = initialize_camera()
    if camera is None:
        cleanup()
        sys.exit(1)

    servo_azimuth, servo_elevation = initialize_servos()
    if servo_azimuth is None or servo_elevation is None:
        cleanup()
        sys.exit(1)

    api = initialize_api()
    if api is None:
        cleanup()
        sys.exit(1)

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame")
                break

            object_rect = segment_red_object(frame)

            if object_rect:
                x, y, w, h = object_rect
                center_x = x + w // 2
                center_y = y + h // 2

                if center_x < CAMERA_WIDTH // 4:
                    send_command(api, 'a')
                elif center_x < CAMERA_WIDTH // 2:
                    send_command(api, 'b')
                elif center_x < CAMERA_WIDTH * 3 // 4:
                    send_command(api, 'g')
                else:
                    send_command(api, 'j')

                if center_y < CAMERA_HEIGHT // 4:
                    send_command(api, 'k')
                else:
                    send_command(api, 'c')

                if w * h < 16 * 16:
                    send_command(api, 'd')
                elif w * h < 32 * 32:
                    send_command(api, 'f')
                else:
                    send_command(api, 'h')
            else:
                send_command(api, 'h')
                if servo_elevation.value < SERVO_MAX_DUTY_CYCLE / 100.0:
                    servo_elevation.value += SERVO_INCREMENT
                else:
                    servo_elevation.value = SERVO_INITIAL_DUTY_CYCLE / 100.0

            time.sleep(0.033)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

