import json
import logging
import signal
import sys
import time
from collections import deque
from typing import Optional, Tuple

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DEFAULT_CONFIG = {
    "offset_1": 0.0,
    "offset_2": 0.0,
    "offset_3": 0.0,
    "max_distance_1": 200.0,
    "max_distance_2": 200.0,
    "max_distance_3": 200.0,
    "low_threshold": 10.0,
    "high_threshold": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

running = True

_SENSOR_CONFIG = {
    1: {"trigger": 17, "echo": 18, "offset": 0.0, "max_distance": 200.0, "errors": 0},
    2: {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0, "errors": 0},
    3: {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0, "errors": 0},
}


def load_config(config_file: str) -> dict:
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(cfg)
        return merged
    except FileNotFoundError:
        logging.warning("Config file not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config file: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_file: str) -> None:
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def setup_gpio() -> bool:
    if GPIO is None:
        logging.error("RPi.GPIO not available; running in mock mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        for cfg in _SENSOR_CONFIG.values():
            GPIO.setup(cfg["trigger"], GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(cfg["echo"], GPIO.IN)
        return True
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return False


def read_distance(sensor_id: int) -> Optional[float]:
    cfg = _SENSOR_CONFIG[sensor_id]
    trigger = cfg["trigger"]
    echo = cfg["echo"]
    max_distance = cfg["max_distance"]

    try:
        GPIO.output(trigger, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger, GPIO.LOW)

        timeout_start = time.time()
        while GPIO.input(echo) == GPIO.LOW:
            if time.time() - timeout_start > 0.05:
                logging.warning(f"Sensor {sensor_id}: echo start timeout")
                return None

        pulse_start = time.time()
        while GPIO.input(echo) == GPIO.HIGH:
            if time.time() - pulse_start > 0.05:
                logging.warning(f"Sensor {sensor_id}: echo pulse timeout")
                return None

        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        distance = distance - cfg["offset"]

        if distance < 2.0 or distance > max_distance:
            logging.warning(
                f"Sensor {sensor_id}: distance {distance:.2f} out of range "
                f"(2-{max_distance})"
            )
            return None

        return distance

    except Exception as e:
        logging.error(f"Sensor {sensor_id} read error: {e}")
        return None


def get_water_level(readings: list) -> Optional[float]:
    if not readings:
        return None
    return sum(readings) / len(readings)


def check_alerts(
    water_level: Optional[float],
    low_threshold: float,
    high_threshold: float,
    alert_repeat_delay: int,
) -> None:
    if water_level is None:
        return
    if water_level < low_threshold:
        logging.warning(
            f"Low water level alert: {water_level:.2f} cm "
            f"(threshold: {low_threshold} cm)"
        )
    elif water_level > high_threshold:
        logging.warning(
            f"High water level alert: {water_level:.2f} cm "
            f"(threshold: {high_threshold} cm)"
        )


def signal_handler(signum, frame) -> None:
    global running
    logging.info(f"Signal {signum} received; shutting down.")
    running = False


def main() -> None:
    global running

    config = load_config("config.json")
    setup_logging(config["log_file"])

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not setup_gpio():
        logging.error("GPIO initialization failed; exiting.")
        sys.exit(0)

    low_threshold = config["low_threshold"]
    high_threshold = config["high_threshold"]
    alert_repeat_delay = config["alert_repeat_delay"]
    last_alert_time = 0.0

    try:
        while running:
            readings = []
            for sid in _SENSOR_CONFIG:
                if _SENSOR_CONFIG[sid]["errors"] >= 5:
                    logging.warning(f"Sensor {sid} disabled due to errors.")
                    continue
                dist = read_distance(sid)
                if dist is not None:
                    readings.append(dist)
                else:
                    _SENSOR_CONFIG[sid]["errors"] += 1

            water_level = get_water_level(readings)
            if water_level is not None:
                logging.info(f"Water level: {water_level:.2f} cm")
                check_alerts(
                    water_level,
                    low_threshold,
                    high_threshold,
                    alert_repeat_delay,
                )
            else:
                logging.warning("No valid sensor readings; skipping alert check.")

            time.sleep(5)

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if GPIO is not None:
            GPIO.cleanup()
        logging.info("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

