import sys
import time
import signal
import random
import logging
import threading
import wave
import contextlib

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except (ImportError, RuntimeError):
    _GPIO_AVAILABLE = False

try:
    import board
    import adafruit_dht
    _DHT_AVAILABLE = True
except (ImportError, RuntimeError):
    _DHT_AVAILABLE = False

try:
    from picamera2 import Picamera2
    _PICAMERA2_AVAILABLE = True
except ImportError:
    _PICAMERA2_AVAILABLE = False

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"
LISTEN_TIMEOUT = 5
SAMPLE_RATE = 16000
SAMPLE_WIDTH = 2
CHUNK_SIZE = 1024

_running = True
_lock = threading.Lock()
_gpio_initialized = False
_camera = None
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False


def _simulate_gpio_setup():
    global _gpio_initialized
    logging.warning("RPi.GPIO not available, simulating GPIO.")
    _gpio_initialized = True


def _simulate_gpio_output(pin, value):
    logging.debug(f"Simulated GPIO output pin {pin} set to {value}")


def _simulate_gpio_cleanup():
    global _gpio_initialized
    logging.warning("Simulating GPIO cleanup.")
    _gpio_initialized = False


def _init_gpio():
    global _gpio_initialized
    if _GPIO_AVAILABLE:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
            _gpio_initialized = True
            logging.info("GPIO initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            _simulate_gpio_setup()
    else:
        _simulate_gpio_setup()


def _cleanup_gpio():
    global _gpio_initialized
    if _gpio_initialized:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            GPIO.cleanup()
            _gpio_initialized = False
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error during GPIO cleanup: {e}")
    else:
        _simulate_gpio_cleanup()


def _init_camera():
    global _camera
    if _PICAMERA2_AVAILABLE:
        try:
            _camera = Picamera2()
            _camera.configure(_camera.create_still_configuration())
            _camera.start()
            logging.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            _camera = None
    return False


def _cleanup_camera():
    global _camera
    if _camera is not None:
        try:
            _camera.stop()
            _camera.close()
            _camera = None
            logging.info("Camera cleaned up.")
        except Exception as e:
            logging.error(f"Error during camera cleanup: {e}")


def _init_dht():
    global _dht_device
    if _DHT_AVAILABLE:
        try:
            _dht_device = adafruit_dht.DHT11(board.D4)
            logging.info("DHT11 sensor initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize DHT11 sensor: {e}")
            _dht_device = None
    return False


def _cleanup_dht():
    global _dht_device
    if _dht_device is not None:
        try:
            _dht_device.exit()
            _dht_device = None
            logging.info("DHT11 sensor cleaned up.")
        except Exception as e:
            logging.error(f"Error during DHT11 cleanup: {e}")


def _read_temperature():
    if _dht_device is not None:
        try:
            temperature = _dht_device.temperature
            if temperature is not None:
                return temperature
            logging.warning("DHT11 returned None temperature.")
        except RuntimeError as e:
            logging.warning(f"DHT11 read error (checksum or timeout): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT11 error: {e}")
    return random.uniform(15, 35)


def _control_lights(command):
    if not _gpio_initialized:
        logging.warning("GPIO not initialized, cannot control lights.")
        return
    try:
        if "turn on the lights" in command:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            logging.info("Lights turned on.")
        elif "turn off the lights" in command:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            logging.info("Lights turned off.")
        else:
            logging.warning("Invalid light command.")
    except Exception as e:
        logging.error(f"Error controlling lights: {e}")


def _take_picture():
    if _camera is None:
        logging.warning("Camera not available.")
        return
    try:
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        _camera.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
    except Exception as e:
        logging.error(f"Error taking picture: {e}")


def _listen_for_wake_word():
    logging.info("Listening for wake word...")
    try:
        with contextlib.closing(wave.open(sys.stdin.buffer, 'rb')) as wf:
            sr = wf.getframerate()
            if sr != SAMPLE_RATE:
                logging.warning(f"Sample rate mismatch: expected {SAMPLE_RATE}, got {sr}")
            wf.setpos(0)
            data = wf.readframes(CHUNK_SIZE)
            while data and _running:
                max_val = max(data)
                if max_val > 0:
                    rms = (sum(map(lambda x: x * x, data)) / len(data)) ** 0.5
                    if rms > 3000:
                        logging.info("Wake word detected!")
                        return True
                data = wf.readframes(CHUNK_SIZE)
    except Exception as e:
        logging.error(f"Error listening for wake word: {e}")
    return False


def _process_command(command):
    if "turn on the lights" in command or "turn off the lights" in command:
        _control_lights(command)
    elif "what is the temperature" in command:
        temp = _read_temperature()
        logging.info(f"Temperature: {temp:.2f} °C")
    elif "take a picture" in command:
        _take_picture()
    else:
        logging.warning("Unknown command.")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_gpio()
    _init_camera()
    _init_dht()

    try:
        while _running:
            if _listen_for_wake_word():
                logging.info("Listening for command...")
                try:
                    with contextlib.closing(wave.open(sys.stdin.buffer, 'rb')) as wf:
                        sr = wf.getframerate()
                        if sr != SAMPLE_RATE:
                            logging.warning(f"Sample rate mismatch: expected {SAMPLE_RATE}, got {sr}")
                        wf.setpos(0)
                        data = wf.readframes(CHUNK_SIZE)
                        command = ""
                        while data and _running:
                            max_val = max(data)
                            if max_val > 0:
                                rms = (sum(map(lambda x: x * x, data)) / len(data)) ** 0.5
                                if rms > 3000:
                                    logging.info("Command detected!")
                                    break
                            data = wf.readframes(CHUNK_SIZE)
                        if not _running:
                            break
                        while data and _running:
                            max_val = max(data)
                            if max_val > 0:
                                rms = (sum(map(lambda x: x * x, data)) / len(data)) ** 0.5
                                if rms > 3000:
                                    break
                            data = wf.readframes(CHUNK_SIZE)
                            if data:
                                command += data.decode('utf-8', errors='ignore')
                        if command:
                            logging.info(f"Command: {command}")
                            _process_command(command.lower())
                except Exception as e:
                    logging.error(f"Error processing command: {e}")
    finally:
        _cleanup_gpio()
        _cleanup_camera()
        _cleanup_dht()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

