import cv2
import select
import sys
import time
import signal
import config
import hardware

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _is_button_up(box):
    try:
        return box.button.is_up
    except Exception:
        return False

def _lock_box(box):
    try:
        box.lock()
    except Exception:
        pass

def _unlock_box(box):
    try:
        box.unlock()
    except Exception:
        pass

def _capture_and_process(box, camera):
    try:
        if not _is_button_up(box):
            return False
        if not camera.read():
            return False
        image = camera.image
        if image is None:
            return False
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(gray, 1.3, 5)
        if len(faces) == 0:
            return False
        x, y, w, h = faces[0]
        cropped = gray[y:y + h, x:x + w]
        resized = cv2.resize(cropped, (10, 10))
        label, confidence = recognizer.predict(resized)
        return label == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > confidence > 1500
    except Exception:
        return False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    box = None
    camera = None
    try:
        box = hardware.Box()
        box.lock()
        face_cascade = cv2.CascadeClassifier(config.FACE_CASCADE_PATH)
        if face_cascade.empty():
            raise RuntimeError("Failed to load Haar cascade")
        recognizer = cv2.face.EigenFaceRecognizer_create()
        recognizer.read(config.TRAINING_FILE)
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise RuntimeError("Failed to open camera")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 64)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 48)
        camera.set(cv2.CAP_PROP_FORMAT, cv2.CAP_PROP_FORMAT_BGR888)
        while _running:
            if _capture_and_process(box, camera):
                _unlock_box(box)
            elif box.is_unlocked:
                _lock_box(box)
            time.sleep(0.1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if camera is not None:
            camera.release()
        if box is not None:
            try:
                box.lock()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

