import cv2
import time
import os
import signal
import sys
import numpy as np

CONFIG_FILE = "config.txt"
DEFAULT_RESOLUTION = (640, 480)
DEFAULT_ROI = (0, 0, 640, 480)
DEFAULT_MOTION_THRESHOLD = 1.0
DEFAULT_SNAPSHOT_DIR = "snapshots"
DEFAULT_CONFIRMATION_DELAY = 5
DEFAULT_TEMPERATURE_THRESHOLD = 80.0
DEFAULT_SIMULATED_TEMPERATURE = False

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    config = {}
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                try:
                    if "." in value:
                        config[key] = float(value)
                    else:
                        config[key] = int(value)
                except ValueError:
                    config[key] = value
    except FileNotFoundError:
        print(f"Warning: Configuration file '{config_file}' not found. Using defaults.")
    except Exception as e:
        print(f"Error reading configuration file: {e}. Using defaults.")
    return config

def parse_config(config):
    resolution = tuple(config.get("resolution", DEFAULT_RESOLUTION))
    roi = tuple(config.get("roi", DEFAULT_ROI))
    motion_threshold = config.get("motion_threshold", DEFAULT_MOTION_THRESHOLD)
    snapshot_dir = config.get("snapshot_dir", DEFAULT_SNAPSHOT_DIR)
    confirmation_delay = config.get("confirmation_delay", DEFAULT_CONFIRMATION_DELAY)
    temperature_threshold = config.get("temperature_threshold", DEFAULT_TEMPERATURE_THRESHOLD)
    simulated_temperature = config.get("simulated_temperature", DEFAULT_SIMULATED_TEMPERATURE)
    return resolution, roi, motion_threshold, snapshot_dir, confirmation_delay, temperature_threshold, simulated_temperature

def initialize_camera(resolution):
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, resolution[0])
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, resolution[1])
        actual_width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        actual_height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        if actual_width != resolution[0] or actual_height != resolution[1]:
            print(f"Warning: Requested resolution {resolution} but got {actual_width}x{actual_height}")
        return cap
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(cap):
    try:
        ret, frame = cap.read()
        if not ret or frame is None:
            raise IOError("Failed to capture frame")
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def detect_motion(frame1, frame2, roi, motion_threshold):
    try:
        x1, y1, x2, y2 = roi
        roi1 = frame1[y1:y2, x1:x2]
        roi2 = frame2[y1:y2, x1:x2]
        diff = cv2.absdiff(roi1, roi2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        motion_percentage = float(np.count_nonzero(thresh)) / thresh.size * 100.0
        return motion_percentage > motion_threshold
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False

def save_snapshot(frame, snapshot_dir):
    try:
        os.makedirs(snapshot_dir, exist_ok=True)
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(snapshot_dir, f"motion_{timestamp}.jpg")
        success = cv2.imwrite(filename, frame)
        if success:
            print(f"Snapshot saved: {filename}")
        else:
            print(f"Error: Failed to write snapshot to {filename}")
    except Exception as e:
        print(f"Error saving snapshot: {e}")

def get_cpu_temperature(simulated):
    if simulated:
        return 70.0 + np.random.uniform(-5, 5)
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp_str = f.read().strip()
            return float(temp_str) / 1000.0
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def check_temperature(temperature, temperature_threshold):
    if temperature is None:
        return False
    return temperature > temperature_threshold

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    config = load_config(CONFIG_FILE)
    resolution, roi, motion_threshold, snapshot_dir, confirmation_delay, temperature_threshold, simulated_temperature = parse_config(config)
    cap = initialize_camera(resolution)
    if cap is None:
        sys.exit(1)
    try:
        while running:
            frame1 = capture_frame(cap)
            if frame1 is None:
                time.sleep(0.1)
                continue
            time.sleep(0.1)
            frame2 = capture_frame(cap)
            if frame2 is None:
                continue
            if detect_motion(frame1, frame2, roi, motion_threshold):
                print("Motion detected!")
                time.sleep(confirmation_delay)
                if detect_motion(frame1, frame2, roi, motion_threshold):
                    print("Motion confirmed!")
                    save_snapshot(frame1, snapshot_dir)
                    temperature = get_cpu_temperature(simulated_temperature)
                    if check_temperature(temperature, temperature_threshold):
                        print(f"Temperature alert: CPU temperature {temperature:.1f}°C exceeds threshold {temperature_threshold}°C")
            frame1 = frame2
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if cap is not None:
            cap.release()
        cv2.destroyAllWindows()
        print("Program terminated.")

if __name__ == "__main__":
    main()

