import signal
import sys
import time
import numpy as np
import sounddevice as sd
from gpiozero import Button

BUTTON_PIN = 5
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
BOUNCE_TIME = 0.2

gain = 1.0
button = None
stream = None
running = True


def toggle_gain():
    global gain
    gain = 2.0 if gain == 1.0 else 1.0
    print(f"Gain toggled to {gain}")


def apply_distortion(in_data, gain_val):
    return np.tanh(in_data * gain_val)


def audio_callback(indata, outdata, frames, time_info, status):
    if status:
        print(f"Stream status: {status}", file=sys.stderr)
    try:
        outdata[:] = apply_distortion(indata, gain)
    except Exception as exc:
        print(f"Audio processing error: {exc}", file=sys.stderr)


def cleanup(signum=None, frame=None):
    global running, stream, button
    running = False
    if stream is not None:
        try:
            if stream.active:
                stream.stop()
        except Exception:
            pass
        try:
            stream.close()
        except Exception:
            pass
        stream = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)


def main():
    global button, stream

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=BOUNCE_TIME)
        button.when_pressed = toggle_gain
    except Exception as exc:
        print(f"Failed to initialize GPIO button on pin {BUTTON_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        stream = sd.Stream(
            samplerate=SAMPLE_RATE,
            blocksize=BLOCK_SIZE,
            channels=1,
            dtype='float32',
            callback=audio_callback,
        )
        stream.start()
    except Exception as exc:
        print(f"Failed to open audio stream: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("Audio distortion control ready. Press Ctrl+C to exit.")
    try:
        while running:
            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

