import signal
import sys
import time
import threading

import cv2
import numpy as np

import config
import face
import mixer

# ---------------------------------------------------------------------------
# Globals for clean shutdown
# ---------------------------------------------------------------------------
_running = True
_lock = threading.Lock()


def _signal_handler(signum, frame):
    global _running
    with _lock:
        _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


class Door:
    """Encapsulates the door lock actuator and button on GPIO18/17."""

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self._lock = None
        self._button = None
        self._init_gpio()

    def _init_gpio(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.lock_pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(self.button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            self._lock = GPIO
            self._button = GPIO
        except Exception as exc:
            raise RuntimeError(f"GPIO initialization failed: {exc}") from exc

    def lock(self):
        if self._lock is not None:
            self._lock.output(self.lock_pin, GPIO.LOW)

    def unlock(self):
        if self._lock is not None:
            self._lock.output(self.lock_pin, GPIO.HIGH)

    def is_button_up(self):
        if self._button is not None:
            return self._button.input(self.button_pin) == GPIO.HIGH
        return False

    def cleanup(self):
        if self._lock is not None:
            try:
                self._lock.output(self.lock_pin, GPIO.LOW)
            except Exception:
                pass
            try:
                self._lock.cleanup()
            except Exception:
                pass
            self._lock = None
            self._button = None


class FaceRecognizer:
    """Wraps the OpenCV EigenFaceRecognizer with a config-driven model path."""

    def __init__(self):
        self.recognizer = None
        self._load_model()

    def _load_model(self):
        try:
            self.recognizer = cv2.face.EigenFaceRecognizer_create()
            self.recognizer.read(config.TRAINING_FILE)
        except Exception as exc:
            raise RuntimeError(f"Failed to load training data: {exc}") from exc

    def recognize(self, image):
        try:
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            label, confidence = self.recognizer.predict(gray)
            return int(label), float(confidence)
        except Exception as exc:
            raise RuntimeError(f"Face recognition failed: {exc}") from exc


def play_sound(sound, mixer_channel):
    """Play a Sound object on the given mixer channel."""
    try:
        mixer_channel.play(sound)
    except Exception as exc:
        print(f"Warning: sound playback failed: {exc}", file=sys.stderr)


def main():
    door = None
    face_recognizer = None
    sound_mixer = None
    sound_channel = None
