    global _running
    with _lock:
        _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


class Door:
    """Encapsulates the door lock actuator and button on GPIO18/17."""

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self._lock = None
        self._button = None
        self._init_gpio()

    def _init_gpio(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.lock_pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(self.button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            self._lock = GPIO
            self._button = GPIO
        except Exception as exc:
            raise RuntimeError(f"GPIO initialization failed: {exc}") from exc

    def lock(self):
        if self._lock is not None:
            self._lock.output(self.lock_pin, GPIO.LOW)

    def unlock(self):
        if self._lock is not None:
            self._lock.output(self.lock_pin, GPIO.HIGH)

    def is_button_up(self):
        if self._button is not None:
            return self._button.input(self.button_pin) == GPIO.HIGH
        return False

    def cleanup(self):
        if self._lock is not None:
            try:
                self._lock.output(self.lock_pin, GPIO.LOW)
            except Exception:
                pass
            try:
                self._lock.cleanup()
            except Exception:
                pass
            self._lock = None
            self._button = None


