    global _running
    _running = False

def read_thermal_temp():
    try:
        with open(THERMAL_ZONE_FILE, 'r') as f:
            millideg = int(f.read().strip())
        return millideg / 1000.0
    except FileNotFoundError:
        print(f"Error: Thermal zone file not found: {THERMAL_ZONE_FILE}")
        return None
    except PermissionError:
        print(f"Error: Permission denied reading {THERMAL_ZONE_FILE}")
        return None
    except (ValueError, OSError) as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        if smbus2 is not None:
            try:
                bus = smbus2.SMBus(I2C_BUS_NUMBER)
                print(f"I2C bus {I2C_BUS_NUMBER} initialized successfully.")
            except OSError as e:
                print(f"Warning: I2C bus {I2C_BUS_NUMBER} unavailable ({e}); continuing without I2C check.")
                bus = None
        else:
            print("Warning: smbus2 library not installed; continuing without I2C check.")

        while _running:
            temp = read_thermal_temp()
            if temp is not None:
                print(f"CPU Temperature: {temp:.2f} °C")
            time.sleep(SLEEP_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        print("Exiting program.")

if __name__ == '__main__':
    main()

