import signal
import sys
import time
import logging

import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("oled_env")

I2C_BUS = 1
OLED_ADDR = 0x3C
BME280_ADDR = 0x76
TSL2561_ADDR = 0x50

running = True


def _signal_handler(signum, frame):
    global running
    log.info("Signal %s received – shutting down.", signum)
    running = False


def _read_bme280(bus):
    """Read temperature (°C), humidity (%), pressure (hPa) from BME280."""
    try:
        data = bus.read_i2c_block_data(BME280_ADDR, 0xF7, 8)
        raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
        raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        raw_hum = (data[6] << 8) | data[7]

        # Temperature: signed 20-bit, 0.01 °C per LSB
        temp = raw_temp / 100.0
        # Humidity: signed 16-bit, 0.01 %RH per LSB
        hum = raw_hum / 100.0
        # Pressure: unsigned 20-bit, 0.01 hPa per LSB
        press = raw_press / 100.0
        return temp, hum, press
    except OSError as exc:
        log.warning("BME280 read failed: %s", exc)
        return None, None, None


def _read_tsl2561(bus):
    """Read light level (lux) from TSL2561."""
    try:
        data = bus.read_i2c_block_data(TSL2561_ADDR, 0x12, 2)
        raw = (data[1] << 8) | data[0]
        lux = raw * 0.04
        return lux
    except OSError as exc:
        log.warning("TSL2561 read failed: %s", exc)
        return None


def _init_oled(serial):
    """Initialize the SSD1306 OLED; return device or None on failure."""
    try:
        return ssd1306(serial, width=128, height=64)
    except Exception as exc:
        log.error("OLED init failed: %s", exc)
        return None


def _init_bus():
    """Open the I2C bus; return bus object or None on failure."""
    try:
        return smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        log.error("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        return None


def _check_devices(bus):
    """Verify that BME280 and TSL2561 are present on the bus."""
    try:
        bus.read_byte(BME280_ADDR)
    except OSError:
        log.error("BME280 not found at 0x%02X", BME280_ADDR)
        return False
    try:
        bus.read_byte(TSL2561_ADDR)
    except OSError:
        log.error("TSL2561 not found at 0x%02X", TSL2561_ADDR)
        return False
    return True


def main():
    global running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = _init_bus()
    if bus is None:
        sys.exit(1)

    serial = i2c(port=I2C_BUS, address=OLED_ADDR)
    oled = _init_oled(serial)
    if oled is None:
        bus.close()
        sys.exit(1)

    if not _check_devices(bus):
        oled.cleanup()
        bus.close()
        sys.exit(1)

    log.info("All devices detected. Entering main loop.")

    try:
        while running:
            temp, hum, press = _read_bme280(bus)
            light = _read_tsl2561(bus)

            lines = []
            if temp is not None:
                lines.append(f"Temp: {temp:.1f} C")
            if hum is not None:
                lines.append(f"Humidity: {hum:.1f} %")
            if press is not None:
                lines.append(f"Pressure: {press:.1f} hPa")
            if light is not None:
                lines.append(f"Light: {light:.1f} lux")

            with canvas(oled) as draw:
                for i, line in enumerate(lines):
                    draw.text((0, i * 12), line, fill="white")

            time.sleep(1)
    finally:
        log.info("Cleaning up resources.")
        try:
            oled.clear()
        except Exception:
            pass
        try:
            oled.cleanup()
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass
        log.info("Done.")


if __name__ == "__main__":
    main()

