import json
import random
import signal
import sys
import threading
import time

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
TOPIC = "classroom/temperature"
KEEPALIVE = 60
NUM_READINGS = 5
RETRY_DELAY = 2
MAX_RETRIES = 3

shutdown_event = threading.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Connection failed with reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code != 0:
        print(f"Publish failed for message ID {mid} with reason code: {reason_code}")


def generate_temperature():
    return round(random.uniform(19.00, 26.00), 2)


def create_payload(index):
    return json.dumps({"temperature": generate_temperature(), "index": index})


def publish_message(client, payload, index):
    try:
        info = client.publish(TOPIC, payload, qos=1)
        info.wait_for_publish(timeout=10)
        print(f"Published: {payload} (mid={info.mid})")
        return True
    except Exception as e:
        print(f"Error publishing message {index}: {e}")
        return False


def connect_and_publish(broker, port, topic, keepalive, num_readings):
    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-publisher",
    )
    client.on_connect = on_connect
    client.on_publish = on_publish

    connected = False
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            client.connect(broker, port, keepalive=keepalive)
            connected = True
            break
        except Exception as e:
            print(f"Connection attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)

    if not connected:
        print("Failed to connect to MQTT broker after multiple retries.")
        return False

    client.loop_start()

    try:
        published_count = 0
        for i in range(num_readings):
            if shutdown_event.is_set():
                print("Shutdown requested; stopping publish loop.")
                break

            payload = create_payload(i)
            if publish_message(client, payload, i):
                published_count += 1
            else:
                print(f"Failed to publish message {i}; continuing to next message.")

            if i < num_readings - 1:
                shutdown_event.wait(1.0)

        print(f"Published {published_count}/{num_readings} messages successfully.")
        return published_count == num_readings
    finally:
        client.loop_stop()
        client.disconnect()
        print("Disconnected from MQTT broker.")


def signal_handler(signum, frame):
    print(f"\nSignal {signum} received; initiating shutdown.")
    shutdown_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    success = connect_and_publish(BROKER, PORT, TOPIC, KEEPALIVE, NUM_READINGS)
    sys.exit(0 if success else 1)


if __name__ == "__main__":
    main()

