import time
import logging
import signal
import smbus2

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("DHT20")


class DHT20:
    """Driver for the DHT20 temperature/humidity sensor on Raspberry Pi I2C bus 1."""

    I2C_BUS = 1
    I2C_ADDRESS = 0x77
    STATUS_REG = 0x71
    DATA_REG = 0x00
    POWER_ON_DELAY = 0.5
    READ_TIMEOUT = 0.1
    RETRY_DELAY = 2.0
    MAX_RETRIES = 5
    STATUS_OK_MASK = 0x18
    STATUS_OK_VALUE = 0x18
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self, bus_num=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        self._closed = False
        try:
            self.bus = smbus2.SMBus(bus_num)
        except OSError as exc:
            logger.error("Failed to open I2C bus %d: %s", bus_num, exc)
            raise
        time.sleep(self.POWER_ON_DELAY)
        if not self._check_status():
            self.close()
            raise RuntimeError("DHT20 status check failed after power-on delay")
        logger.info("DHT20 initialized on bus %d at address 0x%02X", bus_num, address)

    def _check_status(self):
        try:
            status = self.bus.read_byte_data(self.address, self.STATUS_REG)
            return (status & self.STATUS_OK_MASK) == self.STATUS_OK_VALUE
        except OSError as exc:
            logger.error("I2C read of status register failed: %s", exc)
            return False

    def _crc8(self, data):
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_raw(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, self.DATA_REG, 7)
        except OSError as exc:
            logger.error("I2C block read failed: %s", exc)
            return None
        if len(data) != 7:
            logger.error("Unexpected data length: %d", len(data))
            return None
        crc_recv = data[6]
        crc_calc = self._crc8(data[:6])
        if crc_recv != crc_calc:
            logger.warning("CRC mismatch: calculated 0x%02X, received 0x%02X", crc_calc, crc_recv)
            return None
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        return humidity_raw, temp_raw

    def read(self):
        for attempt in range(1, self.MAX_RETRIES + 1):
            if self._closed:
                logger.error("I2C bus closed; cannot read sensor")
                return None, None, True
            try:
                status = self.bus.read_byte_data(self.address, self.STATUS_REG)
            except OSError as exc:
                logger.error("I2C read of status register failed: %s", exc)
                return None, None, True
            if (status & 0x80) == 0:
                break
            if attempt < self.MAX_RETRIES:
                logger.warning("Sensor busy (status=0x%02X); retrying in %.1fs", status, self.RETRY_DELAY)
                time.sleep(self.RETRY_DELAY)
        else:
            logger.error("Sensor did not become ready after %d retries", self.MAX_RETRIES)
            return None, None, True
        raw = self._read_raw()
        if raw is None:
            return None, None, True
        humidity_raw, temp_raw = raw
        humidity = (humidity_raw / 0x100000) * 100.0
        temperature = (temp_raw / 0x100000) * 200.0 - 50.0
        return temperature, humidity, False

    def close(self):
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
            except OSError as exc:
                logger.warning("Error closing I2C bus: %s", exc)
            finally:
                self.bus = None
                self._closed = True

    def __del__(self):
        self.close()


def _main():
    sensor = None
    def _signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down", signum)
        if sensor is not None:
            sensor.close()
        raise SystemExit(0)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        sensor = DHT20(bus_num=1, address=0x77)
        for i in range(3):
            temp, hum, crc_err = sensor.read()
            if crc_err:
                logger.error("Read %d: CRC error", i + 1)
            else:
                logger.info("Read %d: T=%.2f °C  H=%.2f %%", i + 1, temp, hum)
            time.sleep(1.0)
    except Exception as exc:
        logger.error("Fatal error: %s", exc)
    finally:
        if sensor is not None:
            sensor.close()


if __name__ == "__main__":
    _main()

