import signal
import sys
import time
import logging
from typing import Optional, Tuple

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

DHT20_I2C_BUS = 1
DHT20_I2C_ADDR = 0x77
DHT20_STATUS_REG = 0x71
DHT20_DATA_REG = 0x00
DHT20_RESET_REG = 0xBA
DHT20_RESET_CMD = 0xBA
DHT20_STATUS_OK = 0x18
DHT20_MEASURE_CMD = 0xAC
DHT20_MEASURE_CMD_MSB = 0x33
DHT20_MEASURE_CMD_LSB = 0x00
DHT20_MEASURE_DELAY = 0.01
DHT20_MEASURE_TIMEOUT = 0.1
DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INIT = 0xFF


class DHT20:
    def __init__(self, bus_num: int = DHT20_I2C_BUS, addr: int = DHT20_I2C_ADDR):
        self.addr = addr
        self.bus: Optional[smbus.SMBus] = None
        try:
            self.bus = smbus.SMBus(bus_num)
        except OSError as exc:
            logger.error("Failed to open I2C bus %d: %s", bus_num, exc)
            self.bus = None
            return

        if not self._verify_sensor():
            logger.error("DHT20 not detected at address 0x%02X on bus %d", addr, bus_num)
            self._close_bus()
            return

        logger.info("DHT20 initialized on bus %d at address 0x%02X", bus_num, addr)

    def _close_bus(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _verify_sensor(self) -> bool:
        if self.bus is None:
            return False
        try:
            status = self.bus.read_byte_data(self.addr, DHT20_STATUS_REG)
            return status == DHT20_STATUS_OK
        except OSError as exc:
