import time
import signal
import sys
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initializes the I2C bus using board.SCL and board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to verify it is actually connected
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if not devices:
            print("Error: No I2C devices found on the bus.")
            return None
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
        return multiplexer
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None

def initialize_bme280(multiplexer, channel):
    """Initializes the BME280 sensor on the specified multiplexer channel."""
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[channel], address=0x76)
        return bme280
    except Exception as e:
        print(f"Error initializing BME280 on channel {channel}: {e}")
        return None

def initialize_tsl2591(multiplexer, channel):
    """Initializes the TSL2591 sensor on the specified multiplexer channel."""
    try:
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[channel])
        return tsl2591
    except Exception as e:
        print(f"Error initializing TSL2591 on channel {channel}: {e}")
        return None

def read_sensor_data(sensor, sensor_name):
    """Reads data from a sensor with error handling."""
    try:
        if sensor_name == "BME280":
            temperature = sensor.temperature
            humidity = sensor.humidity
            return temperature, humidity
        elif sensor_name == "TSL2591":
            lux = sensor.lux
            return lux
        else:
            return None
    except Exception as e:
        print(f"Error reading {sensor_name} data: {e}")
        return None

def display_sensor_data(temperature, humidity, lux):
    """Displays the sensor data to the console."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
    if lux is not None:
        print(f"Light Intensity: {lux:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        sys.exit(1)

    bme280 = initialize_bme280(multiplexer, 0)
    tsl2591 = initialize_tsl2591(multiplexer, 1)

    if bme280 is None and tsl2591 is None:
        print("Error: No sensors initialized. Exiting.")
        sys.exit(1)

    print("Starting sensor readings. Press Ctrl+C to exit.")

    try:
        while _running:
            temperature = None
            humidity = None
            lux = None

            if bme280 is not None:
                temperature, humidity = read_sensor_data(bme280, "BME280")

            if tsl2591 is not None:
                lux = read_sensor_data(tsl2591, "TSL2591")

            display_sensor_data(temperature, humidity, lux)

            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(20):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("\nExiting program.")

if __name__ == "__main__":
    main()

