import serial
import time
import sys
import os

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1.0
LOG_FILE = 'temperature_log.csv'

def open_serial_port():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False
        )
        return ser
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        return None

def ensure_log_header(ser):
    if not os.path.exists(LOG_FILE):
        try:
            with open(LOG_FILE, 'w', newline='') as f:
                f.write("Timestamp,Temperature_C,Temperature_F\n")
        except OSError as e:
            print(f"Error: Could not create log file {LOG_FILE}: {e}", file=sys.stderr)
            return False
    return True

def read_temperature(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Warning: Malformed data received (not numeric): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Warning: Serial read error: {e}", file=sys.stderr)
        return None

def log_temperature(timestamp, celsius, fahrenheit):
    try:
        with open(LOG_FILE, 'a', newline='') as f:
            f.write(f"{timestamp},{celsius:.2f},{fahrenheit:.2f}\n")
    except OSError as e:
        print(f"Error: Could not write to log file {LOG_FILE}: {e}", file=sys.stderr)

def main():
    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    if not ensure_log_header(ser):
        ser.close()
        sys.exit(1)

    try:
        while True:
            celsius = read_temperature(ser)
            if celsius is not None:
                fahrenheit = (celsius * 9.0 / 5.0) + 32.0
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_temperature(timestamp, celsius, fahrenheit)
                print(f"{timestamp}  Celsius: {celsius:.2f}  Fahrenheit: {fahrenheit:.2f}")
            time.sleep(1.0)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

