import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi.")
    sys.exit(1)

HEATER_PIN = 17
TEMP_MIN = 10
TEMP_MAX = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_temperature():
    return random.randint(TEMP_MIN, TEMP_MAX - 1)

def control_heater(temperature):
    if temperature < 20:
        GPIO.output(HEATER_PIN, GPIO.HIGH)
        print("Heater ON")
    else:
        GPIO.output(HEATER_PIN, GPIO.LOW)
        print("Heater OFF")

def cleanup():
    try:
        GPIO.output(HEATER_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(HEATER_PIN, GPIO.OUT, initial=GPIO.LOW)

    try:
        for i in range(ITERATIONS):
            if not _running:
                break
            temperature = read_temperature()
            print(f"Temperature: {temperature}°C")
            control_heater(temperature)
            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

