    fan_on = temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD
    try:
        GPIO.output(FAN_PIN, GPIO.HIGH if fan_on else GPIO.LOW)
    except Exception as e:
        print(f"Error controlling fan: {e}", file=sys.stderr)


