    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            print(f"Warning: could not initialize GPIO: {e}", file=sys.stderr)
            GPIO = None

    dht_device = None
    if adafruit_dht is not None and board is not None:
        try:
            dht_device = adafruit_dht.DHT11(board.D17)
        except Exception as e:
            print(f"Warning: could not initialize DHT11: {e}", file=sys.stderr)
            dht_device = None

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            timestamp = datetime.now().isoformat(timespec="seconds")
            temperature = None
            humidity = None

            if dht_device is not None:
                try:
                    temperature = dht_device.temperature
                    humidity = dht_device.humidity
                except RuntimeError as e:
                    print(f"DHT11 read error: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"Unexpected DHT11 error: {e}", file=sys.stderr)
            else:
                print("DHT11 sensor not available; skipping reading.", file=sys.stderr)

            if temperature is not None and humidity is not None:
                log_data(timestamp, temperature, humidity)
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, "
                      f"Timestamp: {timestamp}")
                control_fan(temperature, humidity)
            else:
                print("Skipping fan control due to sensor read failure.")

            readings_taken += 1
            if _running and readings_taken < NUM_READINGS:
                time.sleep(READ_INTERVAL)

    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        print("Program finished.")


