import time
import datetime
import csv
import os
import fcntl
import random
import signal
import sys
import traceback

try:
    import board
    import adafruit_dht
except ImportError:
    print("Missing required libraries. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

# Configuration
DHT_PIN_1 = board.D17
DHT_PIN_2 = board.D27
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
HIGH_HUMIDITY_DURATION = 3
LOW_HUMIDITY_DURATION = 3
ALERT_COOLDOWN = 30 * 60
DATA_LOGGING_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2

# Global state
running = True
high_humidity_alerts_suppressed = {DHT_PIN_1: 0, DHT_PIN_2: 0}
low_humidity_alerts_suppressed = {DHT_PIN_1: 0, DHT_PIN_2: 0}
high_humidity_counts = {DHT_PIN_1: 0, DHT_PIN_2: 0}
low_humidity_counts = {DHT_PIN_1: 0, DHT_PIN_2: 0}

# File paths
ERROR_LOG_FILE = "error.log"
DATA_LOG_FILE = "retail_data.csv"
ALERT_LOG_FILE = "retail_alerts.log"
CLOUD_LOG_FILE = "cloud_log.log"

# Initialize DHT22 sensors
dht_devices = {}
try:
    dht_devices[DHT_PIN_1] = adafruit_dht.DHT22(DHT_PIN_1, use_pulseio=False)
    dht_devices[DHT_PIN_2] = adafruit_dht.DHT22(DHT_PIN_2, use_pulseio=False)
except Exception as e:
    log_error(f"Failed to initialize DHT22 sensors: {e}")
    sys.exit(1)

def log_error(message):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"CRITICAL: Cannot write to error log: {e}")

def log_data(timestamp, sensor_id, temperature, humidity):
    try:
        filename = f"retail_data_{timestamp.strftime('%Y-%m-%d')}.csv"
        file_exists = os.path.isfile(filename)
        with open(filename, "a", newline="") as csvfile:
            fieldnames = ["Timestamp", "Sensor ID", "Temperature (C)", "Humidity (%)"]
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if not file_exists:
                writer.writeheader()
            writer.writerow({
                "Timestamp": timestamp.isoformat(),
                "Sensor ID": sensor_id,
                "Temperature (C)": temperature,
                "Humidity (%)": humidity
            })
    except Exception as e:
        log_error(f"Error writing to data file: {e}")

def log_alert(timestamp, sensor_id, alert_type):
    try:
        with open(ALERT_LOG_FILE, "a") as f:
            f.write(f"{timestamp.isoformat()} - ALERT: {sensor_id} - {alert_type}\n")
    except Exception as e:
        log_error(f"Error writing to alert log: {e}")

def simulate_cloud_push(timestamp, sensor_id, temperature, humidity, alert_type):
    try:
        with open(CLOUD_LOG_FILE, "a") as f:
            f.write(f"{timestamp.isoformat()} - CLOUD: {sensor_id} - {temperature}C, {humidity}% - {alert_type}\n")
        if random.random() < 0.8:
            print(f"Simulated cloud push: {sensor_id} - {alert_type}")
        else:
            log_error(f"Simulated cloud push failed for {sensor_id} - {alert_type}")
    except Exception as e:
        log_error(f"Error writing to cloud log: {e}")

def read_dht22(sensor_id):
    max_retries = MAX_RETRIES
    for attempt in range(max_retries):
        try:
            temperature = dht_devices[sensor_id].temperature
            humidity = dht_devices[sensor_id].humidity
            if temperature is not None and humidity is not None:
                if 0 <= humidity <= 100 and -40 <= temperature <= 80:
                    return temperature, humidity
                else:
                    log_error(f"Invalid data from {sensor_id}: Temperature={temperature}, Humidity={humidity}")
                    return None, None
            else:
                log_error(f"Failed to read from {sensor_id}: None values returned")
                return None, None
        except RuntimeError as e:
            log_error(f"RuntimeError reading {sensor_id}: {e}")
            time.sleep(RETRY_DELAY)
        except Exception as e:
            log_error(f"Unexpected error reading {sensor_id}: {e}")
            return None, None
    log_error(f"Failed to read {sensor_id} after {max_retries} retries")
    return None, None

def check_alerts(timestamp, sensor_id, temperature, humidity):
    global high_humidity_alerts_suppressed, low_humidity_alerts_suppressed
    global high_humidity_counts, low_humidity_counts

    if humidity is None:
        return

    if humidity > HIGH_HUMIDITY_THRESHOLD:
        high_humidity_counts[sensor_id] += 1
        low_humidity_counts[sensor_id] = 0
        if high_humidity_counts[sensor_id] >= HIGH_HUMIDITY_DURATION and (timestamp - high_humidity_alerts_suppressed[sensor_id]).total_seconds() > ALERT_COOLDOWN:
            log_alert(timestamp, sensor_id, "High Humidity Alert")
            simulate_cloud_push(timestamp, sensor_id, temperature, humidity, "High Humidity Alert")
            high_humidity_alerts_suppressed[sensor_id] = timestamp
            high_humidity_counts[sensor_id] = 0
    else:
        high_humidity_counts[sensor_id] = 0

    if humidity < LOW_HUMIDITY_THRESHOLD:
        low_humidity_counts[sensor_id] += 1
        high_humidity_counts[sensor_id] = 0
        if low_humidity_counts[sensor_id] >= LOW_HUMIDITY_DURATION and (timestamp - low_humidity_alerts_suppressed[sensor_id]).total_seconds() > ALERT_COOLDOWN:
            log_alert(timestamp, sensor_id, "Low Humidity Alert")
            simulate_cloud_push(timestamp, sensor_id, temperature, humidity, "Low Humidity Alert")
            low_humidity_alerts_suppressed[sensor_id] = timestamp
            low_humidity_counts[sensor_id] = 0
    else:
        low_humidity_counts[sensor_id] = 0

def signal_handler(sig, frame):
    global running
    print("\nShutting down gracefully...")
    running = False

def cleanup():
    for sensor_id in dht_devices:
        try:
            dht_devices[sensor_id].exit()
        except Exception:
            pass
    print("GPIO cleanup complete.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Starting retail environment monitoring...")
    print(f"Logging to {DATA_LOG_FILE}, {ALERT_LOG_FILE}, {CLOUD_LOG_FILE}, {ERROR_LOG_FILE}")

    try:
        while running:
            timestamp = datetime.datetime.now()
            sensor_id = DHT_PIN_1
            temperature, humidity = read_dht22(sensor_id)
            if temperature is not None and humidity is not None:
                log_data(timestamp, sensor_id, temperature, humidity)
                check_alerts(timestamp, sensor_id, temperature, humidity)
            else:
                log_error(f"Failed to read data from {sensor_id}")

            sensor_id = DHT_PIN_2
            temperature, humidity = read_dht22(sensor_id)
            if temperature is not None and humidity is not None:
                log_data(timestamp, sensor_id, temperature, humidity)
                check_alerts(timestamp, sensor_id, temperature, humidity)
            else:
                log_error(f"Failed to read data from {sensor_id}")

            time.sleep(DATA_LOGGING_INTERVAL)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
        traceback.print_exc()
    finally:
        cleanup()

if __name__ == "__main__":
    main()

