import time
import signal
import sys
import paho.mqtt.client as mqtt
import config
import dht22

DEGREE_CELSIUS = '\u00B0C'

running = True
mqtt_client = None
dht_sensor = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global mqtt_client, dht_sensor
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker, reason code: {reason_code}")

def publish_sensor_data(client, temperature, humidity):
    try:
        temperature_topic = f"homie/{config.homieclientid}/{config.homienodes}/temperature"
        humidity_topic = f"homie/{config.homieclientid}/{config.homienodes}/humidity"
        client.publish(temperature_topic, f"{temperature:.1f}", qos=1)
        client.publish(humidity_topic, f"{humidity:.1f}", qos=1)
        print(f"Published: Temp={temperature:.1f}{DEGREE_CELSIUS}, Humidity={humidity:.1f}%")
    except Exception as e:
        print(f"Error publishing data: {e}")

def main():
    global mqtt_client, dht_sensor

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_sensor = dht22.DHT22(config.dhtgpiopin)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    try:
        mqtt_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
