import subprocess
import time
import logging
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    PWMOutputDevice = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def get_cpu_temp():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        return float(result.stdout.strip().split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as exc:
        logger.error("Failed to read CPU temperature: %s", exc)
        return None


def compute_duty_cycle(temp):
    if temp is None:
        return None
    if temp >= 45:
        return 100
    if temp >= 40:
        return 80
    if temp >= 35:
        return 60
    if temp >= 30:
        return 40
    return 20


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
    if PWMOutputDevice is not None:
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
            logger.info("PWM fan initialized on GPIO%d @ %d Hz.", FAN_PIN, PWM_FREQ)
        except Exception as exc:
            logger.warning("Could not initialize PWM on GPIO%d: %s", FAN_PIN, exc)
            fan = None
    else:
        logger.warning("gpiozero not available – running in degraded mode.")

    last_duty = 0
    degraded = fan is None

    try:
        while _running:
            temp = get_cpu_temp()
            if temp is not None:
                duty = compute_duty_cycle(temp)
                if duty is not None:
                    last_duty = duty
                    if not degraded and fan is not None:
                        try:
                            fan.value = duty / 100.0
                        except Exception as exc:
                            logger.error("Failed to set PWM duty cycle: %s", exc)
                    else:
                        logger.info("Temp: %.1f°C  ->  duty: %d%% (degraded mode)", temp, duty)
                else:
                    logger.warning("Temperature %.1f°C out of range – keeping last duty cycle (%d%%).", temp, last_duty)
            else:
                logger.warning("Temperature read failed – keeping last duty cycle (%d%%).", last_duty)

            for _ in range(CHECK_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
            except Exception:
                pass
        logger.info("Fan control stopped.")


if __name__ == "__main__":
    main()

