import signal
import sys
import time

import gpiozero

PWM_PIN = 18
ON_THRESHOLD = 40.0
LOW_SPEED = 20.0
HIGH_SPEED = 100.0
POLL_INTERVAL = 5.0

fan = None
running = True


def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f'Error reading CPU temperature: {e}', file=sys.stderr)
        return None


def main():
    global fan
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = gpiozero.PWMOutputDevice(PWM_PIN, frequency=25000, initial_value=0.0)
    except Exception as e:
        print(f'Failed to initialize PWM on GPIO{PWM_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    print(f'Fan control started on GPIO{PWM_PIN} (BCM).')
    print(f'Threshold: {ON_THRESHOLD}°C  Low: {LOW_SPEED}%  High: {HIGH_SPEED}%')
    print('Press Ctrl+C to exit.\n')

    while running:
        temp = read_cpu_temp()
        if temp is not None:
            if temp > ON_THRESHOLD:
                fan.value = HIGH_SPEED / 100.0
                print(f'Temp: {temp:.1f}°C  ->  Fan: {HIGH_SPEED}%')
            else:
                fan.value = LOW_SPEED / 100.0
                print(f'Temp: {temp:.1f}°C  ->  Fan: {LOW_SPEED}%')
        else:
            print('Skipping cycle due to temperature read failure.')
        time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == '__main__':
    main()

