import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_INTERVAL = 1
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        return None
    except Exception:
        return None

def write_to_serial(ser, data):
    try:
        payload = f"{data[0]},{data[1]}\n"
        ser.write(payload.encode('ascii'))
        ser.flush()
    except Exception:
        pass

def check_alerts(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print(f"ALERT: Temperature {temperature:.1f}°C exceeds threshold {TEMP_THRESHOLD}°C")
    if humidity > HUMIDITY_THRESHOLD:
        print(f"ALERT: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud")

        while running:
            data = read_sensor_data(ser)
            if data is not None:
                temperature, humidity = data
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_alerts(temperature, humidity)
                write_to_serial(ser, data)
            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Serial port error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

