import time
import sys
import signal

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Please install it via 'sudo apt install python3-rpi.gpio'.")
    sys.exit(1)

LED_PIN = 17
led_state = False

def cleanup_gpio(signum=None, frame=None):
    """Safely clean up GPIO resources on exit."""
    global led_state
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
        led_state = False
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)

def main():
    global led_state

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, cleanup_gpio)
    signal.signal(signal.SIGINT, cleanup_gpio)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on', 'off', or 'exit': ").strip().lower()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == "on":
                GPIO.output(LED_PIN, GPIO.HIGH)
                led_state = True
                print(f"LED is now ON: led_state = {led_state}")
            elif user_input == "off":
                GPIO.output(LED_PIN, GPIO.LOW)
                led_state = False
                print(f"LED is now OFF: led_state = {led_state}")
            elif user_input == "exit":
                print("Exiting program.")
                break
            else:
                print("Invalid input")

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

