import signal
import sys
import time

import RPi.GPIO as GPIO

SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as exc:
        print(f"Error: failed to initialize GPIO: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for pin in SENSOR_PINS:
            try:
                GPIO.setup(pin, GPIO.IN, pull_up=True)
            except Exception as exc:
                print(f"Error: failed to configure GPIO {pin}: {exc}", file=sys.stderr)
                GPIO.cleanup()
                sys.exit(1)

        print(f"Monitoring sensors on pins {SENSOR_PINS} every {POLL_INTERVAL}s. Press Ctrl+C to exit.")

        while _running:
            try:
                for pin in SENSOR_PINS:
                    try:
                        if GPIO.input(pin):
                            print(f"Response for sensor {pin}")
                    except Exception as exc:
                        print(f"Warning: error reading GPIO {pin}: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Warning: unexpected error in poll loop: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

