import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two TCRT5000 sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Number of samples to collect
NUM_SAMPLES = 10

# Delay between samples in seconds
SAMPLE_DELAY = 0.5


def setup_gpio():
    """Configure the GPIO pins for the TCRT5000 sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"Error setting up GPIO: {e}", file=sys.stderr)
        sys.exit(1)


def read_sensor(pin):
    """Read a single TCRT5000 sensor and return its value (0 or 1)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}", file=sys.stderr)
        return None


def describe_steering(left_value, right_value):
    """
    Determine the steering direction based on the sensor readings.
    Returns a human-readable string.
    """
    if left_value is None or right_value is None:
        return "ERROR"
    if left_value == 0 and right_value == 0:
        return "forward"
    if left_value == 1 and right_value == 0:
        return "turn-left"
    if left_value == 0 and right_value == 1:
        return "turn-right"
    return "search"


def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}", file=sys.stderr)


def main():
    """Main loop: read sensors and print steering direction."""
    setup_gpio()
    try:
        for i in range(NUM_SAMPLES):
            left_value = read_sensor(LEFT_SENSOR_PIN)
            right_value = read_sensor(RIGHT_SENSOR_PIN)

            if left_value is not None and right_value is not None:
                print(
                    f"Sample {i + 1}/{NUM_SAMPLES}: "
                    f"Left={left_value}, Right={right_value} -> "
                    f"Steering: {describe_steering(left_value, right_value)}"
                )
            else:
                print(
                    f"Sample {i + 1}/{NUM_SAMPLES}: "
                    f"Sensor read error -> Steering: ERROR"
                )

            time.sleep(SAMPLE_DELAY)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

