import signal
import threading
import time

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    raise


class OutputPin:
    """Generic output pin wrapper using gpiozero."""

    def __init__(self, name: str, pin: int, initial_value: int = 0):
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a non-empty string")
        if not isinstance(pin, int) or not (0 <= pin <= 53):
            raise ValueError("pin must be an integer between 0 and 53 (BCM numbering)")
        if initial_value not in (0, 1):
            raise ValueError("initial_value must be 0 or 1")

        self.name = name
        self.pin = pin
        self.initial_value = initial_value
        self._device = None
        self._lock = threading.Lock()
        self._closed = False

        try:
            self._device = OutputDevice(pin, active_high=True, initial_value=bool(initial_value))
        except (GPIOZeroError, GPIODeviceError) as e:
            raise RuntimeError(f"Failed to initialize GPIO {pin} ({name}): {e}") from e

    def set_value(self, value: int) -> None:
        if self._closed:
            raise RuntimeError(f"Pin {self.name} is closed and cannot be written")
        if value not in (0, 1):
            raise ValueError("value must be 0 or 1")
        with self._lock:
            if self._device is not None:
                self._device.value = bool(value)

    def get_value(self) -> int:
        if self._closed:
            raise RuntimeError(f"Pin {self.name} is closed and cannot be read")
        with self._lock:
            if self._device is not None:
                return int(self._device.value)
            return self.initial_value

    def shutdown(self) -> None:
        if self._closed:
            return
        with self._lock:
            if self._device is not None:
                try:
                    self._device.close()
                except Exception:
                    pass
                self._device = None
            self._closed = True

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(name='{self.name}', pin={self.pin}, initial_value={self.initial_value})"


class TriggerPin(OutputPin):
    """Output pin that can generate a 100 us high pulse."""

    def __init__(self, name: str, pin: int, pulse_high: bool = True, pulse_duration: float = 1e-5):
        if not isinstance(pulse_duration, (int, float)) or pulse_duration <= 0:
            raise ValueError("pulse_duration must be a positive number (seconds)")
        initial_value = 0 if pulse_high else 1
        super().__init__(name, pin, initial_value)
        self.pulse_high = pulse_high
        self.pulse_duration = float(pulse_duration)

    def trigger(self) -> None:
        if self._closed:
            raise RuntimeError(f"Pin {self.name} is closed and cannot be triggered")
        with self._lock:
            if self._device is None:
                raise RuntimeError(f"Pin {self.name} device is not initialized")
            try:
                self._device.value = self.pulse_high
                time.sleep(self.pulse_duration)
                self._device.value = not self.pulse_high
            except Exception as e:
                raise RuntimeError(f"Failed to trigger pin {self.name}: {e}") from e

    def __repr__(self) -> str:
        return (
            f"{self.__class__.__name__}(name='{self.name}', pin={self.pin}, "
            f"pulse_high={self.pulse_high}, pulse_duration={self.pulse_duration})"
        )


# ---------------------------------------------------------------------------
# Example usage
# ---------------------------------------------------------------------------
example_output = OutputPin("ExampleOutput", 21, initial_value=0)
example_trigger = TriggerPin("ExampleTrigger", 20, pulse_high=True, pulse_duration=1e-5)


def _signal_handler(signum, frame):
    print(f"\nSignal {signum} received. Shutting down pins...")
    example_output.shutdown()
    example_trigger.shutdown()
    print("Shutdown complete.")


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

try:
    print(f"ExampleOutput initial value: {example_output.get_value()}")
    print(f"ExampleTrigger initial value: {example_trigger.get_value()}")

    example_output.set_value(1)
    print(f"ExampleOutput set to 1 (high)")
    time.sleep(0.5)

    example_output.set_value(0)
    print(f"ExampleOutput set to 0 (low)")
    time.sleep(0.5)

    print("Triggering 100 us high pulse...")
    example_trigger.trigger()
    print("Pulse complete.")
except Exception as e:
    print(f"Runtime error: {e}")
finally:
    example_output.shutdown()
    example_trigger.shutdown()

