import time
import board
import busio
import adafruit_fingerprint

# Initialize I2C bus on GPIO 3 (SCL) and GPIO 2 (SDA)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize the fingerprint sensor
try:
    fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
except ValueError as e:
    print(f"Fatal: Fingerprint sensor not found on I2C bus: {e}")
    i2c_bus.deinit()
    raise SystemExit(1)
except Exception as e:
    print(f"Fatal: Failed to initialize fingerprint sensor: {e}")
    i2c_bus.deinit()
    raise SystemExit(1)

# Main authentication loop
try:
    while True:
        try:
            # Wait for a finger to be placed on the sensor
            print("Waiting for finger...")
            while True:
                try:
                    if fingerprint_sensor.get_image() == adafruit_fingerprint.OK:
                        break
                except OSError as e:
                    print(f"I2C bus error during get_image(): {e}")
                    time.sleep(1)
                    continue
                except Exception as e:
                    print(f"Unexpected error during get_image(): {e}")
                    time.sleep(1)
                    continue
                time.sleep(0.1)

            # Convert the image to a template
