import signal
import sys
import time

import board
import busio
import adafruit_tsl2561
from gpiozero import PWMOutputDevice

LED_PIN = 18
PWM_FREQ = 1000
UPDATE_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c = None
    led = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor = adafruit_tsl2561.TSL2561(i2c)
        sensor.enabled = True
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
    except Exception as exc:
        print(f"Error: TSL2561 not found on I2C bus (check wiring/address): {exc}", file=sys.stderr)
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        sys.exit(1)

    try:
        led = PWMOutputDevice(LED_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as exc:
        print(f"Error: failed to initialize PWM on GPIO{LED_PIN}: {exc}", file=sys.stderr)
        try:
            sensor.enabled = False
        except Exception:
            pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        sys.exit(1)

    try:
        while _running:
            try:
                lux = sensor.lux
            except Exception as exc:
                print(f"Warning: lux read failed: {exc}", file=sys.stderr)
                lux = None

            if lux is not None:
                duty = max(0.0, min(100.0, (lux / 100.0)))
                led.value = duty / 100.0
                print(f"Lux: {lux:.2f}  Duty: {duty:.1f}%")
            else:
                led.value = 0.0
                print("Lux: N/A  Duty: 0.0%")

            time.sleep(UPDATE_INTERVAL)
    finally:
        if led is not None:
            try:
                led.value = 0.0
                led.close()
            except Exception:
                pass
        try:
            sensor.enabled = False
        except Exception:
            pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

