import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi.")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000

_running = True
_pwm = None


def _cleanup():
    global _pwm
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _signal_handler(signum, frame):
    global _running
    _running = False


def _set_fan_speed(speed_percent):
    if not 0 <= speed_percent <= 100:
        print("Invalid speed. Please enter a value between 0 and 100.")
        return
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(speed_percent)
        except Exception as e:
            print(f"Error setting fan speed: {e}")
    else:
        print(f"Fan speed set to: {speed_percent:.1f}% (software PWM unavailable)")


def main():
    global _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    try:
        GPIO.setup(FAN_PIN, GPIO.OUT)
    except Exception as e:
        print(f"Error setting up GPIO pin {FAN_PIN}: {e}")
        _cleanup()
        sys.exit(1)

    try:
        _pwm = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
        _pwm.start(0)
    except Exception as e:
        print(f"Warning: hardware PWM unavailable ({e}); falling back to software PWM.")
        _pwm = None

    try:
        while _running:
            try:
                user_input = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                break

            if user_input.lower() == 'q':
                break

            try:
                fan_speed = float(user_input)
            except ValueError:
                print("Invalid input. Please enter a number.")
                continue

            _set_fan_speed(fan_speed)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

