#!/usr/bin/env python3
"""
Raspberry Pi GPIO monitoring program.

Auto-detects the Pi model, configures every pin in gpio_ch as a debounced
input, records state-change events in a rolling in-memory log, and runs
until a SIGINT/SIGTERM is received.
"""

import argparse
import signal
import sys
import time

try:
    from gpiozero import Button
    from gpiozero.pins.native import NativeFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Model detection
# ---------------------------------------------------------------------------

def get_raspi_model():
    """Return the Raspberry Pi model name based on the board revision code."""
    try:
        with open("/proc/cpuinfo", "r") as f:
            for line in f:
                if line.startswith("Revision"):
                    rev_hex = line.split(":")[1].strip()
                    rev_code = int(rev_hex, 16)
