#!/usr/bin/env python3
"""
LED Blinker for Raspberry Pi 4

Blinks an LED on GPIO17 (BCM) with 0.5 s on/off intervals.
Handles KeyboardInterrupt and GPIO errors gracefully.
"""

import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
    sys.exit(1)

LED_PIN = 17
BLINK_INTERVAL = 0.5  # seconds


def setup_gpio(pin: int) -> None:
    """Initialize GPIO mode and set the LED pin as an output, initially off."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)


def blink_led(pin: int, interval: float) -> None:
    """Continuously blink the LED until interrupted."""
    while True:
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(interval)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(interval)


def cleanup_gpio(pin: int) -> None:
    """Turn off the LED and release GPIO resources."""
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()


def main() -> None:
    print(f"Starting LED blinker on GPIO{LED_PIN} with {BLINK_INTERVAL}s interval.")
    try:
        setup_gpio(LED_PIN)
        blink_led(LED_PIN, BLINK_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except PermissionError as e:
        print(f"Permission error: {e}. Run with sudo or add user to gpio group.", file=sys.stderr)
    except RuntimeError as e:
        print(f"GPIO runtime error: {e}. Check wiring and permissions.", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio(LED_PIN)
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

