import time
import sys
import signal

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17

led = None
running = True

def cleanup():
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global led

    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected failure initializing GPIO{LED_PIN}: {e}")
        sys.exit(1)

    print(f"Blinking LED on GPIO{LED_PIN} at 1 Hz. Press Ctrl+C to stop.")

    try:
        while running:
            led.on()
            time.sleep(1)
            if not running:
                break
            led.off()
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

