#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter with touchpads, 14-segment display,
APA102 LED strip, and buzzer.

Touchpad A (GPIO5)  -> MSB (value 4)
Touchpad B (GPIO6)  -> middle bit (value 2)
Touchpad C (GPIO12) -> LSB (value 1)
"""

import signal
import sys
import time

try:
    from rainbowhat import display, touch, lights, apa102, buzzer
except ImportError:
    print("Error: rainbowhat library not found. Install with: pip install rainbowhat",
          file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Pin assignments (BCM)
# ---------------------------------------------------------------------------
TOUCH_PINS = {
    "A": 5,
    "B": 6,
    "C": 12,
}

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _cleanup():
    """Turn off all HAT outputs and clear the display."""
    try:
        display.clear()
        display.show()
    except Exception as exc:
        print(f"Warning: display cleanup failed: {exc}", file=sys.stderr)
    try:
        lights.rgb(0, 0, 0)
    except Exception as exc:
        print(f"Warning: RGB LEDs cleanup failed: {exc}", file=sys.stderr)
    try:
        lights.clear()
        lights.show()
    except Exception as exc:
        print(f"Warning: discrete LEDs cleanup failed: {exc}", file=sys.stderr)
    try:
        apa102.clear()
        apa102.show()
    except Exception as exc:
        print(f"Warning: APA102 strip cleanup failed: {exc}", file=sys.stderr)


def _write_14seg(value):
    """Write a decimal value 0-7 to the 14-segment display."""
    try:
        display.clear()
        display.print_int(value)
        display.show()
    except Exception as exc:
        print(f"Error writing to 14-segment display: {exc}", file=sys.stderr)


def _write_led_strip(value):
    """
    Drive the APA102 LED strip.

    index 0 -> dim white when value == 0
    index 0 -> red/green/blue pixel when value > 0
    all 7 pixels white when value == 7
    """
    try:
        apa102.clear()
        if value == 0:
            apa102.set_pixel(0, 0.2, 0.2, 0.2)
        elif value == 7:
            for i in range(7):
                apa102.set_pixel(i, 1.0, 1.0, 1.0)
        else:
            red = 1.0 if value & 4 else 0.0
            green = 1.0 if value & 2 else 0.0
            blue = 1.0 if value & 1 else 0.0
            apa102.set_pixel(0, red, green, blue)
        apa102.show()
    except Exception as exc:
