import signal
import sys

# Define the GPIO pin connected to the LED (BCM numbering)
LED_PIN = 17

# Flag to indicate if the program should exit
running = True

def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) to ensure graceful shutdown."""
    global running
    print("\nInterrupt received, shutting down...")
    running = False

def setup_gpio():
    """Sets up the GPIO pin for output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        print(f"GPIO pin {LED_PIN} configured as output.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def turn_led_on():
    """Turns the LED on."""
    try:
        GPIO.output(LED_PIN, GPIO.HIGH)
        print("LED is ON")
    except Exception as e:
        print(f"Error turning LED on: {e}")

def turn_led_off():
    """Turns the LED off."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        print("LED is OFF")
    except Exception as e:
        print(f"Error turning LED off: {e}")

def cleanup_gpio():
    """Cleans up the GPIO settings."""
    try:
        GPIO.cleanup()
        print("GPIO cleanup completed.")
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

def main():
    """Main function to toggle the LED."""
    global running

    # Register the signal handler for SIGINT
    signal.signal(signal.SIGINT, signal_handler)

    try:
        setup_gpio()

        while running:
            turn_led_on()
            time.sleep(2)

            if not running:
                break

            turn_led_off()
            time.sleep(2)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

