import time
import signal
import contextlib

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    raise

LED_PIN = 18
BLINK_COUNT = 5
ON_DURATION = 1.0
OFF_DURATION = 1.0


def blink_led(led, blink_count, on_duration, off_duration):
    """Blink the LED a specified number of times with specified on/off durations."""
    for i in range(blink_count):
        led.on()
        time.sleep(on_duration)
        led.off()
        time.sleep(off_duration)


@contextlib.contextmanager
def managed_led(pin):
    """Context manager that guarantees the LED is turned off and released."""
    led = LED(pin)
    try:
        yield led
    finally:
        led.off()
        led.close()


def main():
    try:
        with managed_led(LED_PIN) as led:
            blink_led(led, BLINK_COUNT, ON_DURATION, OFF_DURATION)
    except KeyboardInterrupt:
        print("Blinking interrupted by user.")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

