import smbus
import time
import signal
import sys

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x18          # Default I2C address (SDO tied to GND)
WHO_AM_I_REG = 0x0F
WHO_AM_I_EXPECTED = 0x33

LED_PIN = 21
BUZZER_PIN = 20

X_THRESHOLD_G = 0.3
BUZZER_THRESHOLD_G = 0.7
SAMPLE_INTERVAL_S = 0.1
LOOP_DELAY_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_running = True
_bus = None
_led = None
_buzzer = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _cleanup():
    """Turn off outputs and release resources."""
    global _led, _buzzer, _bus
    if _led is not None:
        try:
            _led.off()
        except Exception:
            pass
    if _buzzer is not None:
        try:
            _buzzer.off()
        except Exception:
            pass
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
    _led = None
    _buzzer = None
    _bus = None


def _init_gpio():
    """Initialize GPIO pins using gpiozero. Returns (led, buzzer) or (None, None)."""
    try:
        from gpiozero import LED, Buzzer
        led = LED(LED_PIN)
        buzzer = Buzzer(BUZZER_PIN)
        led.off()
        buzzer.off()
        return led, buzzer
    except Exception as exc:
        print(f"Error initializing GPIO pins: {exc}", file=sys.stderr)
        return None, None


def _init_i2c():
    """Initialize the I2C bus. Returns the bus object or None."""
    try:
        bus = smbus.SMBus(I2C_BUS)
        return bus
    except Exception as exc:
        print(f"Error initializing I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return None


def _verify_device(bus):
    """Verify the LIS3DH WHO_AM_I register. Returns True on success."""
    try:
        who = bus.read_byte_data(LIS3DH_ADDR, WHO_AM_I_REG)
        if who != WHO_AM_I_EXPECTED:
            print(
                f"Error: WHO_AM_I mismatch: got 0x{who:02X}, "
                f"expected 0x{WHO_AM_I_EXPECTED:02X}",
                file=sys.stderr,
            )
            return False
        return True
    except Exception as exc:
        print(f"Error reading WHO_AM_I from 0x{LIS3DH_ADDR:02X}: {exc}", file=sys.stderr)
        return False


def _read_x_acceleration(bus):
    """Read the signed 16-bit X-axis acceleration in g. Returns float or None."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDR, 0x28, 2)
        raw = (data[1] << 8) | data[0]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw * 0.001  # LIS3DH default ±2 g range, 1 mg/LSB
    except Exception as exc:
        print(f"Error reading X-axis acceleration: {exc}", file=sys.stderr)
        return None


def _control_outputs(x_g, led, buzzer):
    """Drive LED and buzzer based on acceleration thresholds."""
    try:
        if x_g is None:
            led.off()
            buzzer.off()
            return

        if abs(x_g) > X_THRESHOLD_G:
            led.on()
        else:
            led.off()

        if abs(x_g) > BUZZER_THRESHOLD_G:
            buzzer.on()
            time.sleep(0.05)  # Short delay after each register write
            buzzer.off()
        else:
            buzzer.off()
    except Exception as exc:
        print(f"Error controlling outputs: {exc}", file=sys.stderr)
        led.off()
        buzzer.off()


def main():
    global _bus, _led, _buzzer

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _led, _buzzer = _init_gpio()
    if _led is None or _buzzer is None:
        _cleanup()
        sys.exit(1)

    _bus = _init_i2c()
    if _bus is None:
        _cleanup()
        sys.exit(1)

    if not _verify_device(_bus):
        _cleanup()
        sys.exit(1)

    print("LIS3DH accelerometer monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            x_g = _read_x_acceleration(_bus)
            if x_g is not None:
                print(f"X-axis acceleration: {x_g:.3f} g")
            _control_outputs(x_g, _led, _buzzer)
            time.sleep(LOOP_DELAY_S)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Program exited cleanly.")


if __name__ == "__main__":
    main()

