import logging
import signal
import sys
import time

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

MOTOR_1 = 1
MOTOR_2 = 2

MOTOR_1_DIR_CW = 0b00000010
MOTOR_1_DIR_CCW = 0b00000001
MOTOR_1_DIR_STOP = 0b00000000

MOTOR_2_DIR_CW = 0b00001000
MOTOR_2_DIR_CCW = 0b00000100
MOTOR_2_DIR_STOP = 0b00000000

ALL_STOP = 0b00000000


class Motor:
    def __init__(self, shield, motor_num, pwm_pin, dir_pins):
        self.shield = shield
        self.motor_num = motor_num
        self.pwm_pin = pwm_pin
        self.dir_pins = dir_pins
        self.pwm = None
        self.is_running = False
        self.current_duty_cycle = 0

    def setup(self):
        try:
            GPIO.setup(self.pwm_pin, GPIO.OUT)
            GPIO.setup(self.dir_pins, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pwm_pin, 100)
            self.pwm.start(0)
            self.shield.directions[self.motor_num - 1] = MOTOR_1_DIR_STOP
            self.shield.write_to_shift_register()
            logging.info(
                f"Motor {self.motor_num} PWM pin {self.pwm_pin} and direction pins {self.dir_pins} setup complete."
            )
        except Exception as e:
            logging.error(f"Error setting up motor {self.motor_num}: {e}")
            raise

    def start(self, duty_cycle):
        if not self.pwm:
            raise RuntimeError(f"Motor {self.motor_num} PWM not initialized.")
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be between 0 and 100, got {duty_cycle}.")
        try:
            self.pwm.ChangeDutyCycle(duty_cycle)
            self.current_duty_cycle = duty_cycle
            self.is_running = True
            logging.info(
                f"Motor {self.motor_num} started at {duty_cycle}% duty cycle."
            )
        except Exception as e:
            logging.error(f"Error starting motor {self.motor_num}: {e}")
            raise

    def stop(self):
        if self.pwm:
            try:
                self.pwm.ChangeDutyCycle(0)
                self.is_running = False
                self.current_duty_cycle = 0
                logging.info(f"Motor {self.motor_num} stopped.")
            except Exception as e:
                logging.error(f"Error stopping motor {self.motor_num}: {e}")
                raise

    def change_duty_cycle(self, duty_cycle):
        if not self.is_running:
            raise RuntimeError(f"Motor {self.motor_num} is not running.")
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be between 0 and 100, got {duty_cycle}.")
        try:
            self.pwm.ChangeDutyCycle(duty_cycle)
            self.current_duty_cycle = duty_cycle
            logging.info(
                f"Motor {self.motor_num} duty cycle changed to {duty_cycle}%."
            )
        except Exception as e:
            logging.error(f"Error changing duty cycle of motor {self.motor_num}: {e}")
            raise

    def set_direction(self, direction):
        if direction not in (
            MOTOR_1_DIR_CW,
            MOTOR_1_DIR_CCW,
            MOTOR_1_DIR_STOP,
            MOTOR_2_DIR_CW,
            MOTOR_2_DIR_CCW,
            MOTOR_2_DIR_STOP,
        ):
            raise ValueError(
                f"Invalid direction {direction}. Must be one of {MOTOR_1_DIR_CW}, {MOTOR_1_DIR_CCW}, {MOTOR_1_DIR_STOP}, {MOTOR_2_DIR_CW}, {MOTOR_2_DIR_CCW}, {MOTOR_2_DIR_STOP}."
            )
        try:
            self.shield.directions[self.motor_num - 1] = direction
            self.shield.write_to_shift_register()
            logging.info(
                f"Motor {self.motor_num} direction set to {direction}."
            )
        except Exception as e:
            logging.error(f"Error setting direction of motor {self.motor_num}: {e}")
            raise

    def close(self):
        self.stop()
        if self.pwm:
            try:
                self.pwm.stop()
            except Exception as e:
                logging.error(f"Error stopping PWM for motor {self.motor_num}: {e}")
            self.pwm = None


class MotorShield:
    def __init__(self, latch_pin, clock_pin, data_pin, motor1_pwm_pin, motor2_pwm_pin):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.motor1_pwm_pin = motor1_pwm_pin
        self.motor2_pwm_pin = motor2_pwm_pin
        self.directions = [MOTOR_1_DIR_STOP, MOTOR_2_DIR_STOP]
        self.motors = []
        self._initialized = False

    def setup(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.latch_pin, GPIO.OUT)
            GPIO.setup(self.clock_pin, GPIO.OUT)
            GPIO.setup(self.data_pin, GPIO.OUT)
            self.write_to_shift_register()
            logging.info(
                f"Shift register pins LATCH={self.latch_pin}, CLOCK={self.clock_pin}, DATA={self.data_pin} setup complete."
            )
            self._initialized = True
        except Exception as e:
            logging.error(f"Error setting up shift register: {e}")
            raise

    def add_motor(self, motor_num, pwm_pin, dir_pins):
        if motor_num not in (MOTOR_1, MOTOR_2):
            raise ValueError(f"Invalid motor number {motor_num}. Must be {MOTOR_1} or {MOTOR_2}.")
        if motor_num == MOTOR_1 and self.motor1_pwm_pin != pwm_pin:
            raise ValueError(
                f"Motor 1 PWM pin mismatch: expected {self.motor1_pwm_pin}, got {pwm_pin}."
            )
        if motor_num == MOTOR_2 and self.motor2_pwm_pin != pwm_pin:
            raise ValueError(
                f"Motor 2 PWM pin mismatch: expected {self.motor2_pwm_pin}, got {pwm_pin}."
            )
        if len(dir_pins) != 2:
            raise ValueError("Direction pins must be a list of exactly two pins.")
        motor = Motor(self, motor_num, pwm_pin, dir_pins)
        motor.setup()
        self.motors.append(motor)
        logging.info(f"Motor {motor_num} added to shield.")

    def write_to_shift_register(self):
        if not self._initialized:
            raise RuntimeError("Shift register not initialized.")
        try:
            GPIO.output(self.latch_pin, GPIO.LOW)
            for i in range(8):
                GPIO.output(self.clock_pin, GPIO.LOW)
                GPIO.output(
                    self.data_pin, GPIO.HIGH if (self.directions[i // 2] >> (i % 2)) & 1 else GPIO.LOW
                )
                GPIO.output(self.clock_pin, GPIO.HIGH)
            GPIO.output(self.latch_pin, GPIO.HIGH)
        except Exception as e:
            logging.error(f"Error writing to shift register: {e}")
            raise

    def start_motor(self, motor_num, duty_cycle):
        if motor_num not in (MOTOR_1, MOTOR_2):
            raise ValueError(f"Invalid motor number {motor_num}. Must be {MOTOR_1} or {MOTOR_2}.")
        motor = next((m for m in self.motors if m.motor_num == motor_num), None)
        if not motor:
            raise RuntimeError(f"Motor {motor_num} not added to shield.")
        motor.start(duty_cycle)

    def stop_motor(self, motor_num):
        if motor_num not in (MOTOR_1, MOTOR_2):
            raise ValueError(f"Invalid motor number {motor_num}. Must be {MOTOR_1} or {MOTOR_2}.")
