import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("smart_agriculture")

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    log.error("gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)


PUMP_PIN = 20
LIGHT_PIN = 21


class ActuatorController:
    """Controls a nutrient pump and a grow light via GPIO digital outputs."""

    def __init__(self, pump_pin: int, light_pin: int):
        self.pump = None
        self.light = None
        try:
            self.pump = OutputDevice(pump_pin, active_high=True, initial_value=False)
            self.light = OutputDevice(light_pin, active_high=True, initial_value=False)
            log.info("Actuators initialized: pump=BCM%d, light=BCM%d", pump_pin, light_pin)
        except GPIOZeroError as exc:
            log.error("Failed to initialize GPIO devices: %s", exc)
            self.close()
            raise

    def apply_intent(self, intent: str) -> None:
        if intent == "pump_on":
            self.pump.on()
            log.info("Pump turned ON")
        elif intent == "pump_off":
            self.pump.off()
            log.info("Pump turned OFF")
        elif intent == "light_toggle":
            self.light.toggle()
            state = "ON" if self.light.is_active else "OFF"
            log.info("Light toggled -> %s", state)
        else:
            log.warning("Unknown intent '%s'; no action taken.", intent)

    def close(self) -> None:
        for name, dev in (("pump", self.pump), ("light", self.light)):
            if dev is not None:
                try:
                    dev.off()
                    dev.close()
                except Exception as exc:
                    log.warning("Error closing %s: %s", name, exc)
        self.pump = None
        self.light = None


def parse_intent(phrase: str) -> str:
    """Return the best matching intent for *phrase* (case-insensitive)."""
    keywords = {
        "pump on": "pump_on",
        "switch light": "light_toggle",
        "turn pump off": "pump_off",
    }
    for keyword, intent in keywords.items():
        if keyword in phrase.lower():
            return intent
    return "unknown"


def main() -> None:
    controller = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True
        log.info("Signal %d received; shutting down.", signum)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller = ActuatorController(PUMP_PIN, LIGHT_PIN)
    except GPIOZeroError:
        log.error("Cannot continue without GPIO devices. Exiting.")
        sys.exit(1)

    phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    for phrase in phrases:
        if shutting_down:
            break
        intent = parse_intent(phrase)
        log.info("Phrase: '%s' -> intent: '%s'", phrase, intent)
        controller.apply_intent(intent)

    controller.close()
    log.info("Actuators shut down cleanly.")


if __name__ == "__main__":
    main()

