import signal
import sys
import time
from datetime import datetime

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# DS1338 I2C address (A0-A2 tied to GND)
DS1338_ADDR = 0x68

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# Control register bit masks
CTRL_CH = 0x80  # Clock Halt (1 = stop, 0 = run)
CTRL_12_24 = 0x00  # 24-hour mode

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def bcd_to_int(bcd):
    """Convert BCD byte to integer."""
    return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)


def int_to_bcd(i):
    """Convert integer (0-99) to BCD byte."""
    if not 0 <= i <= 99:
        raise ValueError(f"Integer {i} out of BCD range 0-99")
    return ((i // 10) << 4) | (i % 10)


def read_register(bus, reg):
    """Read a single byte from a DS1338 register."""
    return bus.read_byte_data(DS1338_ADDR, reg)


def write_register(bus, reg, value):
    """Write a single byte to a DS1338 register."""
    bus.write_byte_data(DS1338_ADDR, reg, value)


def read_all(bus):
    """Read all time/date registers from DS1338."""
    data = bus.read_i2c_block_data(DS1338_ADDR, REG_SECONDS, 7)
    return {
        "seconds": bcd_to_int(data[0] & 0x7F),
        "minutes": bcd_to_int(data[1]),
        "hours": bcd_to_int(data[2] & 0x3F),   # mask bit 6 (12/24 mode)
        "day": bcd_to_int(data[3]),
        "date": bcd_to_int(data[4]),
        "month": bcd_to_int(data[5]),
        "year": bcd_to_int(data[6]),
    }


def read_datetime(bus, century=21):
    """Read date/time and return as datetime object."""
    t = read_all(bus)
    return datetime(
        century * 100 + t["year"],
        t["month"],
        t["date"],
        t["hours"],
        t["minutes"],
        t["seconds"],
    )


def write_all(bus, seconds=None, minutes=None, hours=None, day=None,
              date=None, month=None, year=None):
    """Write all time/date registers. Any None value leaves the register unchanged."""
    now = datetime.now()
    values = {
        "seconds": seconds if seconds is not None else now.second,
        "minutes": minutes if minutes is not None else now.minute,
        "hours": hours if hours is not None else now.hour,
        "day": day if day is not None else now.isoweekday(),
        "date": date if date is not None else now.day,
        "month": month if month is not None else now.month,
        "year": year if year is not None else now.year % 100,
    }

    # Validate ranges
    for name, val in values.items():
        if name == "seconds":
            if not 0 <= val <= 59:
                raise ValueError(f"Seconds {val} out of range 0-59")
        elif name == "minutes":
            if not 0 <= val <= 59:
                raise ValueError(f"Minutes {val} out of range 0-59")
        elif name == "hours":
            if not 0 <= val <= 23:
                raise ValueError(f"Hours {val} out of range 0-23")
        elif name == "day":
            if not 1 <= val <= 7:
                raise ValueError(f"Day {val} out of range 1-7")
        elif name == "date":
            if not 1 <= val <= 31:
                raise ValueError(f"Date {val} out of range 1-31")
        elif name == "month":
            if not 1 <= val <= 12:
                raise ValueError(f"Month {val} out of range 1-12")
        elif name == "year":
            if not 0 <= val <= 99:
                raise ValueError(f"Year {val} out of range 0-99")

    # Build register block
    block = [
        int_to_bcd(values["seconds"]),
        int_to_bcd(values["minutes"]),
        int_to_bcd(values["hours"]),
        int_to_bcd(values["day"]),
        int_to_bcd(values["date"]),
        int_to_bcd(values["month"]),
        int_to_bcd(values["year"]),
    ]

    # Write block in one I2C transaction
    bus.write_i2c_block_data(DS1338_ADDR, REG_SECONDS, block)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error opening I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Verify device presence
        try:
            bus.read_byte_data(DS1338_ADDR, REG_SECONDS)
        except OSError:
            print(f"Error: No DS1338 found at address 0x{DS1338_ADDR:02X} on bus 1.", file=sys.stderr)
            sys.exit(1)

        print("DS1338 detected. Reading current time...")
        try:
            dt = read_datetime(bus)
            print(f"Current time: {dt.strftime('%Y-%m-%d %H:%M:%S')}")
        except OSError as e:
            print(f"Error reading time: {e}", file=sys.stderr)
            sys.exit(1)

        if not _running:
            return

        print("\nWriting new time (current system time)...")
        try:
            write_all(bus)
            print("Write successful.")
        except ValueError as e:
            print(f"Invalid time value: {e}", file=sys.stderr)
            sys.exit(1)
        except OSError as e:
            print(f"Error writing time: {e}", file=sys.stderr)
            sys.exit(1)

        if not _running:
            return

        print("\nReading back...")
        try:
            dt = read_datetime(bus)
            print(f"Time after write: {dt.strftime('%Y-%m-%d %H:%M:%S')}")
        except OSError as e:
            print(f"Error reading time: {e}", file=sys.stderr)
            sys.exit(1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

