import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

running = True
serial_connection = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_connection
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
    try:
        GPIO.cleanup()
        print("GPIO cleaned up.")
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")

def main():
    global serial_connection, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)
        print(f"GPIO {ALARM_PIN} initialized as output (LOW).")
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT
        )
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        GPIO.cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        GPIO.cleanup()
        sys.exit(1)

    alarm_active = False

    try:
        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    radiation_level = float(line)
                except ValueError:
                    print(f"Invalid data received (not numeric): '{line}'")
                    continue

                print(f"Radiation Level: {radiation_level:.2f} µSv/h")

                if radiation_level > RADIATION_THRESHOLD:
                    if not alarm_active:
                        GPIO.output(ALARM_PIN, GPIO.HIGH)
                        alarm_active = True
                        print("Radiation level exceeds threshold! Alarm activated.")
                else:
                    if alarm_active:
                        GPIO.output(ALARM_PIN, GPIO.LOW)
                        alarm_active = False
                        print("Radiation level normal. Alarm deactivated.")

            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
            except Exception as e:
                print(f"Unexpected error in read loop: {e}")

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Fatal error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

