import serial
import logging
import signal
import sys
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            self._connected = True
            logger.info("Connected to GPS on %s @ %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logger.error("Failed to open serial port %s: %s", self.port, exc)
            self.serial_port = None
            self._connected = False
            return False
        except Exception as exc:
            logger.error("Unexpected error opening %s: %s", self.port, exc)
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        if self._connected and self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logger.info("Serial port %s closed", self.port)
            except Exception as exc:
                logger.error("Error closing serial port: %s", exc)
            finally:
                self.serial_port = None
                self._connected = False

    def read_gps_data(self) -> Optional[GPS_readings]:
        if not self._connected or self.serial_port is None:
            logger.warning("Not connected; call connect() first")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as exc:
            logger.error("Serial read error: %s", exc)
            return None
        except Exception as exc:
            logger.error("Unexpected read error: %s", exc)
            return None

        if not raw:
            logger.warning("Read timeout: no data received within 1 second")
            return None

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as exc:
            logger.error("Decode error: %s", exc)
            return None

        if not line:
            return None

        if not line.startswith("$GPGGA"):
            logger.debug("Non-GPGGA sentence ignored: %r", line)
            return None

        fields = line.split(",")
        if len(fields) < 15:
            logger.warning("GPGGA incomplete (got %d fields, expected >= 15): %r", len(fields), line)
            return None

        talker = fields[0][1:3]
        if talker != "GP":
            logger.debug("Non-GPS talker ignored: %r", talker)
            return None

        try:
            utc_time = fields[1]
            latitude_raw = fields[2]
            latitude_dir = fields[3]
            longitude_raw = fields[4]
            longitude_dir = fields[5]
            fix_quality = fields[6]
            satellites = fields[7]
            altitude_raw = fields[9]
            altitude_units = fields[10]
        except IndexError as exc:
            logger.warning("GPGGA field out of range: %s", exc)
            return None

        if not utc_time or not latitude_raw or not latitude_dir or not longitude_raw or not longitude_dir:
            logger.warning("GPGGA missing required coordinate fields: %r", line)
            return None

        if not fix_quality or fix_quality == "0":
            logger.debug("No GPS fix (quality=%r)", fix_quality)
            return None

        try:
            latitude = _ddmm_to_decimal(latitude_raw, latitude_dir)
            longitude = _ddmm_to_decimal(longitude_raw, longitude_dir)
        except ValueError as exc:
            logger.warning("Invalid coordinate values: %s", exc)
            return None

        try:
            altitude = float(altitude_raw) if altitude_raw else 0.0
        except ValueError as exc:
            logger.warning("Invalid altitude value: %s", exc)
            return None

        try:
            satellites = int(satellites)
        except ValueError as exc:
            logger.warning("Invalid satellite count: %s", exc)
            return None

        return GPS_readings(latitude, longitude, altitude, satellites)


def _ddmm_to_decimal(value: str, direction: str) -> float:
    if not value or not direction:
        raise ValueError("Empty coordinate value or direction")
    if direction not in ("N", "S", "E", "W"):
        raise ValueError(f"Invalid direction '{direction}'; expected N/S/E/W")
    dot = value.find(".")
    if dot < 2:
        raise ValueError(f"Invalid ddmm.mmmm format: {value}")
    degrees = float(value[:dot - 2])
    minutes = float(value[dot - 2:])
    decimal = degrees + minutes / 60.0
    if direction in ("S", "W"):
        decimal = -decimal
    return decimal


_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %d received, shutting down...", signum)
    _running = False


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    reader = GPSReader(port="/dev/serial0", baudrate=9600)
    if not reader.connect():
        sys.exit(1)

    try:
        while _running:
            data = reader.read_gps_data()
            if data is not None:
                logger.info(
                    "GPS Fix: Lat=%.6f, Lon=%.6f, Alt=%.2f m, Sats=%d",
                    data.latitude,
                    data.longitude,
                    data.altitude,
                    data.satellites,
                )
    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
    finally:
        reader.disconnect()


if __name__ == "__main__":
    main()

