}
data_lock = threading.Lock()

# Thread-safe UART handle
uart_lock = threading.Lock()
uart_port: Optional[serial.Serial] = None


def open_uart() -> bool:
    """Open /dev/ttyUSB0 at 9600 8N1 with a 1-second read timeout."""
    global uart_port
    if uart_port is not None and uart_port.is_open:
        return True
    with uart_lock:
        if uart_port is not None and uart_port.is_open:
            return True
        try:
            port = serial.Serial(
                port="/dev/ttyUSB0",
                baudrate=9600,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            uart_port = port
