        uart_port = None


def get_uart_response(command: str) -> Optional[str]:
    """Send *IDN?\n and return the stripped response line, or None on error/timeout."""
    if not open_uart():
        return None
    try:
        with uart_lock:
            if uart_port is None or not uart_port.is_open:
                return None
            uart_port.reset_input_buffer()
            uart_port.write(command.encode("ascii"))
            uart_port.flush()
            raw = uart_port.readline()
        if not raw:
            return None
        return raw.decode("ascii", errors="replace").strip()
    except serial.SerialException as exc:
        print(f"UART communication error: {exc}", file=sys.stderr)
        return None


