def create_data_item() -> Response:
    """Create a new data item from JSON body."""
    try:
        payload = request.get_json(silent=True)
        if payload is None:
            return Response("Invalid JSON body.", status=400)
        name = payload.get("name")
        done = payload.get("done", False)
        if not isinstance(name, str) or not name.strip():
            return Response("Invalid or missing 'name' field.", status=400)
        if not isinstance(done, bool):
            return Response("Invalid or missing 'done' field.", status=400)
    except (ValueError, TypeError) as exc:
        return Response(f"Invalid request body: {exc}", status=400)

    with data_lock:
        new_id = max(data_store.keys(), default=0) + 1
        new_item = {"id": new_id, "name": name, "done": done}
        data_store[new_id] = new_item
    return jsonify(new_item), 201


def signal_handler(signum: int, frame: Any) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    close_uart()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        close_uart()

