import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout
        )
        print(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_pulse_oximeter_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        data = raw.decode('ascii', errors='replace').strip()
        if not data:
            return None
        return data
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS read error: {e}", file=sys.stderr)
        return None

def process_data(data):
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: {data!r}")
    heart_rate, spo2 = parts
    return heart_rate.strip(), spo2.strip()

def display_data(heart_rate, spo2):
    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            data = read_pulse_oximeter_data(serial_connection)
            if data is None:
                time.sleep(1)
                continue
            try:
                heart_rate, spo2 = process_data(data)
                display_data(heart_rate, spo2)
            except ValueError as e:
                print(f"Invalid data format: {e}", file=sys.stderr)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

