    global ser
    if ser is not None:
        try:
            if ser.is_open:
                ser.close()
        except Exception as exc:
            print(f"[WARN] Error closing serial port: {exc}", file=sys.stderr)
        finally:
            ser = None


def send_scpi_query(query: str) -> Optional[str]:
    if ser is None or not ser.is_open:
        return None
    try:
        ser.reset_input_buffer()
        ser.write(query.encode("ascii"))
        ser.flush()
        time.sleep(READ_DELAY)
        raw = ser.read(ser.in_waiting or 4096)
        return raw.decode("ascii", errors="replace").strip()
    except serial.SerialException as exc:
        print(f"[ERROR] Serial communication failed: {exc}", file=sys.stderr)
        return None


