            try:
                item = request.get_json(silent=True)
            except Exception as exc:
                print(f"[ERROR] JSON parse failed: {exc}", file=sys.stderr)
                return Response("Invalid JSON", status=400, mimetype="text/plain")
        elif request.content_type == "application/x-www-form-urlencoded":
            item = request.form.to_dict()
        else:
            return Response("Unsupported content type", status=415, mimetype="text/plain")

        if item is None:
            return Response("Empty request body", status=400, mimetype="text/plain")

        try:
            item_id = int(item.get("id", len(data) + 1))
        except (TypeError, ValueError):
            return Response("Invalid 'id' value", status=400, mimetype="text/plain")

